INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C1','kor',6,2,'u1',2,'작가의 의도 알기 — 작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것을 작가의 의도라 하고, 같은 작품도 근거가 있으면 서로 다르게 읽을 수 있음을 알기',ARRAY['6국05 문학(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C2','kor',6,2,'u1',2,'되풀이하거나 힘준 표현에서 뜻 찾기 — 작품에서 되풀이한 말, 물음으로 끝맺는 등 힘준 표현을 찾아 그 표현이 주는 느낌과 담긴 뜻을 생각하기(시조는 세 줄이라 고르고 고른 말이 실마리)',ARRAY['6국05 문학(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C3','kor',6,2,'u1',2,'작가의 삶을 실마리로 작품 다시 읽기 — 작가가 살아온 삶을 알아보아 작품을 다시 보되, 삶만으로 뜻을 하나로 정하지 않고 작품으로 돌아와 근거를 찾기',ARRAY['6국05 문학(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C4','kor',6,2,'u1',4,'시어의 뜻을 짐작하며 시 읽기 — 길·담·닫힌 문·발자국처럼 여러 뜻을 품은 시어가 무엇을 나타내는지 앞뒤 연을 근거로 짐작하고, 여러 번 읽으며 스스로 느낀 것과 짐작한 의도를 근거와 한 묶음으로 말하기',ARRAY['6국05 문학(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C5','kor',6,2,'u1',7,'이야기 구조 알기 — 이야기를 발단(시작)·전개(사건이 본격적으로 생김)·절정(긴장감이 높아지거나 갈등이 두드러짐)·결말(마무리)로 나누고, 경계는 까닭을 말할 수 있으면 사람마다 다를 수 있음을 알기',ARRAY['6국02 읽기(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C6','kor',6,2,'u1',7,'이야기의 줄거리 간추리기 — 부분마다 중요한 사건을 골라, 덜 중요한 것은 덜어 내고, 무슨 일이 왜 일어났는지 이어지도록 짧게 적기(늘어놓기·통째 옮기기·뭉뚱그리기 피하기)',ARRAY['6국02 읽기(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C7','kor',6,2,'u1',9,'인물의 마음과 시간 표현 읽기 — 앞뒤 사건을 근거로 인물의 마음을 짐작하고, 지난여름·여름내·사흘째·이튿날 같은 시간을 나타내는 표현으로 일의 차례를 가려 읽으며, 이야기 속 낱말의 뜻 알기',ARRAY['6국02 읽기(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C8','kor',6,2,'u1',12,'문학 작품 소개하기 — 처음(제목·작가·고른 까닭)·가운데(간추린 줄거리·짐작한 의도와 근거)·끝(내 생각·권할 사람)으로 소개하고, 광고처럼 쓰지 않으며, 찾은 글은 간추려 내 말로 쓰고 출처를 적고, 친구에게 근거를 묻는 물음 하기',ARRAY['6국05 문학(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u1-C9','kor',6,2,'u1',12,'여러 뜻을 지닌 낱말 — 차다·눈·쓰다·타다처럼 글자가 같아도 뜻이 다른 낱말을 앞뒤 문장을 보고 알맞은 뜻으로 가려 읽기(기초 다지기)',ARRAY['6국04 문법(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X01','kor',6,'u1',ARRAY['K6-2-u1-C1']::text[],'작가의 의도를 모두가 똑같이 내야 하는 정답이나 작가가 살던 때의 기록으로 여긴다','쓴 사람 쪽에서 — 「왜 썼을까, 무엇을 느끼길 바랐을까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X02','kor',6,'u1',ARRAY['K6-2-u1-C2','K6-2-u1-C4','K6-2-u1-C6','K6-2-u1-C7']::text[],'작품에 없는 내용(내 짐작·바깥 정보)을 작품에 나온 것으로 고른다','작품에 적힌 말에 밑줄부터 — 적혀 있지 않으면 근거가 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X03','kor',6,'u1',ARRAY['K6-2-u1-C2']::text[],'되풀이하거나 힘준 표현을 그냥 지나가는 말로 여기거나 글자 그대로만 받아들인다(백 번 = 정확히 백 번)','두 번 나온 말, 물음으로 끝난 말에 동그라미 — 왜 힘을 줬을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X04','kor',6,'u1',ARRAY['K6-2-u1-C1','K6-2-u1-C3']::text[],'작가의 삶만 보고 작품의 뜻을 하나로 정해 버리고 작품에서 근거를 찾지 않는다','작가의 삶은 실마리 — 「그렇다면 시의 어느 줄이?」로 돌아가기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X05','kor',6,'u1',ARRAY['K6-2-u1-C3']::text[],'작가의 삶은 작품과 상관없다고 여겨 아예 알아보지 않는다','작가를 알면 그냥 지나친 말이 다시 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X06','kor',6,'u1',ARRAY['K6-2-u1-C1','K6-2-u1-C4','K6-2-u1-C7','K6-2-u1-C8']::text[],'근거 없이 느낌만 말하거나, 근거가 있는 다른 읽기를 틀렸다고 한다','맞고 틀림이 아니라 근거가 있고 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X07','kor',6,'u1',ARRAY['K6-2-u1-C1']::text[],'작품을 감상하는 대신 어느 쪽이 옳은지 내 결론을 말한다','「작가는 무엇을 전하려 했나?」만 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X08','kor',6,'u1',ARRAY['K6-2-u1-C4']::text[],'시어를 겉뜻으로만 읽는다(담 = 집의 생김새, 발자국 = 더러운 자국)','그 낱말이 나온 연에서 인물이 어떤 처지인지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X09','kor',6,'u1',ARRAY['K6-2-u1-C5']::text[],'발단·전개·절정·결말을 헷갈리거나 경계가 하나로만 정해진다고 여긴다','긴장감이 가장 높은 곳(절정)부터 찾고 앞뒤를 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X10','kor',6,'u1',ARRAY['K6-2-u1-C6']::text[],'사건을 늘어놓기만 해서 무슨 일이 왜 일어났는지 이어지지 않는 줄거리를 쓴다','「~해서 ~하자 ~했다」처럼 이음말로 잇기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X11','kor',6,'u1',ARRAY['K6-2-u1-C6','K6-2-u1-C8']::text[],'덜 중요한 것까지 통째로 옮기거나, 반대로 중요한 사건을 빼고 한 문장으로 뭉뚱그린다','부분마다 중요한 사건 하나씩 — 네 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X12','kor',6,'u1',ARRAY['K6-2-u1-C7']::text[],'인물의 마음을 앞뒤 사건 근거 없이 엉뚱하게 짐작한다','「바로 앞에 무슨 일이 있었지? 곁에 누가 있었지?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X13','kor',6,'u1',ARRAY['K6-2-u1-C8']::text[],'작품 소개를 광고하는 말(대박·별 다섯)이나 책값·쪽수처럼 작품과 상관없는 것으로 채운다','읽는 사람이 「어떤 작품인지」 알 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X14','kor',6,'u1',ARRAY['K6-2-u1-C8']::text[],'찾은 글을 그대로 옮겨 붙이고 어디에서 찾았는지 적지 않는다','두세 줄로 간추려 내 말로 + 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X15','kor',6,'u1',ARRAY['K6-2-u1-C7','K6-2-u1-C9']::text[],'낱말만 보고 뜻을 정해 앞뒤 문장에 맞지 않는 뜻을 고른다','그 문장이 무엇에 대한 말인지 먼저 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X16','kor',6,'u1',ARRAY['K6-2-u1-C7']::text[],'시간을 나타내는 표현을 놓쳐 일의 차례나 때를 뒤바꾼다','지난여름·여름내·사흘째·이튿날에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u1-X17','kor',6,'u1',ARRAY['K6-2-u1-C2','K6-2-u1-C4']::text[],'시조·시의 짜임(시조는 세 줄, 시는 연과 행)을 모르거나 표현을 형식 맞추기로만 여긴다','시조 세 줄 · 시는 연(덩어리)과 행(줄)') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#1','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C1',1,'mc','auto','작가의 의도로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X01','K6-2-u1-X02']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"작가의 의도로 알맞은 것은 어느 것인가요?","options":[{"t":"작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것","correct":true},{"t":"작품을 읽고 모두가 똑같이 내야 하는 답","mis":"K6-2-u1-X01"},{"t":"작가가 살던 때에 있었던 일의 기록","mis":"K6-2-u1-X01"},{"t":"작품에 나오는 어려운 낱말의 뜻","mis":"K6-2-u1-X02"}],"explanation":["작가의 의도는 쓴 사람 쪽에서 생각해요.","작가가 왜 썼는지, 읽는 사람이 무엇을 느끼기를 바랐는지가 의도예요.","모두가 똑같이 내야 하는 정답이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#2','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',1,'mc','auto','시조 「같이 건너세」에서 되풀이된 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"시조 「같이 건너세」에서 되풀이된 말은 어느 것인가요?","options":[{"t":"또 한","correct":true},{"t":"길이 되고","mis":"K6-2-u1-X03"},{"t":"한 마을로","mis":"K6-2-u1-X03"},{"t":"건너오면","mis":"K6-2-u1-X03"}],"explanation":["「또 한 돌을」, 「또 한 사람」에 「또 한」이 두 번 나와요.","되풀이된 말은 그냥 지나가는 말이 아니라 눈여겨볼 표시예요.","작은 것이 하나씩 쌓이는 모습이 드러나요."],"asset":{"type":"passage","lines":["돌 하나 또 한 돌을 놓으면 길이 되고","그 길로 또 한 사람 건너오면 이웃이라","우리도 이같이 놓아 한 마을로 살리라"],"title":"시조 「같이 건너세」 — 한도경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#3','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',1,'sa','auto','시조 「나루를 지켜」 첫째 줄에서 두 번 되풀이된 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u1-C2","difficulty":1,"kind":"sa","stem":"시조 「나루를 지켜」 첫째 줄에서 두 번 되풀이된 말을 쓰세요.","answer":["백 번","백번"],"explanation":["「이 나루 백 번 고쳐 백 번을 다시 매도」예요.","「백 번」이 두 번 나와요.","몇 번이 되어도 지키겠다는 뜻을 힘주어 말한 거예요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"},"mis":"K6-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#4','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',1,'mc','auto','시조는 모두 몇 줄로 짓나요?',ARRAY['K6-2-u1-X17']::text[],false,'{"seq":4,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"시조는 모두 몇 줄로 짓나요?","options":[{"t":"세 줄","correct":true},{"t":"두 줄","mis":"K6-2-u1-X17"},{"t":"네 줄","mis":"K6-2-u1-X17"},{"t":"정해진 줄 수가 없어요","mis":"K6-2-u1-X17"}],"explanation":["시조는 고려 말부터 이어 온 우리 고유의 시예요.","정해진 글자 수에 맞추어 세 줄로 지어요.","줄 수가 정해져 있어 하고 싶은 말을 고르고 골라 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#5','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',2,'mc','auto','「백 번 고쳐 백 번을 다시 매도」에 담긴 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X02']::text[],false,'{"seq":5,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「백 번 고쳐 백 번을 다시 매도」에 담긴 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"몇 번이 되어도 나루를 계속 지키겠다는 뜻","correct":true},{"t":"나루를 정확히 백 번 고쳤다는 기록","mis":"K6-2-u1-X03"},{"t":"나루가 자주 고장 나서 불편하다는 불평","mis":"K6-2-u1-X02"},{"t":"나루를 헐고 새로 짓자는 부탁","mis":"K6-2-u1-X02"}],"explanation":["「백 번」을 두 번 되풀이해 힘을 주었어요.","실제 횟수가 아니라 「아무리 여러 번이라도」라는 뜻이에요.","나루를 지키려는 마음을 힘주어 드러냈어요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#6','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',2,'mc','auto','「나루를 지켜」가 「변할 줄이 있으랴」처럼 묻는 말로 끝맺은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X06','K6-2-u1-X17']::text[],false,'{"seq":6,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「나루를 지켜」가 「변할 줄이 있으랴」처럼 묻는 말로 끝맺은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"답을 바라는 물음이 아니라 「변하지 않는다」는 뜻을 힘주어 말하려고","correct":true},{"t":"읽는 사람에게 답을 알려 달라고 하려고","mis":"K6-2-u1-X03"},{"t":"작가도 자기 마음을 몰라서","mis":"K6-2-u1-X06"},{"t":"시조는 언제나 물음으로 끝나야 해서","mis":"K6-2-u1-X17"}],"explanation":["「변할 줄이 있으랴」는 「변할 리가 없다」는 뜻이에요.","묻는 꼴로 끝맺어 오히려 뜻을 세게 말해요.","힘주어 끝맺은 말은 작가의 뜻을 찾는 좋은 실마리예요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#7','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',2,'match','auto','시조의 표현과 그 표현에 담긴 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u1-C2","difficulty":2,"kind":"match","stem":"시조의 표현과 그 표현에 담긴 뜻을 알맞게 이으세요.","pairs":[{"l":"돌 하나 또 한 돌을","r":"작은 것이 쌓여 큰 것이 된다"},{"l":"건너오면 이웃이라","r":"길이 이어지면 사람이 이어진다"},{"l":"변할 줄이 있으랴","r":"내 마음은 바뀌지 않는다"}],"mis":"K6-2-u1-X03","explanation":["되풀이하거나 힘준 표현에는 뜻이 담겨 있어요.","「또 한」의 되풀이는 쌓임, 「이웃」은 사람의 이어짐이에요.","「있으랴」는 묻는 꼴로 마음이 바뀌지 않음을 힘주어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#8','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C3',2,'ox','auto','「한도경은 다리 놓는 사람이었으니까 이 시조는 다리를 놓자는 뜻이다. 끝.」 이렇게 읽으면 충분해요.',ARRAY['K6-2-u1-X04']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":2,"kind":"ox","stem":"「한도경은 다리 놓는 사람이었으니까 이 시조는 다리를 놓자는 뜻이다. 끝.」 이렇게 읽으면 충분해요.","answer":"X","reason_options":[{"t":"작가의 삶은 실마리일 뿐, 다시 작품으로 돌아와 근거를 찾아야 하기 때문에","correct":true},{"t":"작가의 직업이 곧 작품의 뜻이기 때문에","mis":"K6-2-u1-X04"}],"mis":"K6-2-u1-X04","explanation":["작가의 삶을 알면 작품이 다시 보여요.","그렇다고 삶만 보고 뜻을 하나로 정하면 안 돼요.","「왜 ‘이웃’이라고 했을까?」처럼 작품으로 돌아와야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#9','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C1',2,'mc','auto','두 시조를 읽은 뒤 이 시간에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X07','K6-2-u1-X06','K6-2-u1-X05']::text[],false,'{"seq":9,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"두 시조를 읽은 뒤 이 시간에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"각 작가가 무엇을 전하려 했는지 근거를 들어 짐작하기","correct":true},{"t":"다리를 놓는 것과 나루를 지키는 것 가운데 누가 옳은지 겨루기","mis":"K6-2-u1-X07"},{"t":"더 좋은 시조 하나만 골라 외우기","mis":"K6-2-u1-X06"},{"t":"작가의 이름만 외우기","mis":"K6-2-u1-X05"}],"explanation":["두 시조는 같은 일을 두고 서로 다른 뜻을 담았어요.","누가 옳은지 겨루면 작품이 아니라 내 결론을 말하게 돼요.","각자 무엇을 전하려 했는지 근거로 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_basic#10','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C3',3,'error','auto','작가 한도경이 여러 마을을 다니며 다리 놓는 일을 했다는 것을 알고 「같이 건너세」를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X06']::text[],false,'{"seq":10,"concept":"K6-2-u1-C3","difficulty":3,"kind":"error","stem":"작가 한도경이 여러 마을을 다니며 다리 놓는 일을 했다는 것을 알고 「같이 건너세」를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"예강 — 「작가가 다리 놓는 일을 했대. 그러니 이 시조는 더 읽지 않아도 돼.」","correct":true,"mis_target":"K6-2-u1-X04"},{"t":"슬찬 — 「작가의 삶을 알고 나니 ‘또 한 사람’이 다시 보여.」","mis":"K6-2-u1-X06"},{"t":"온새 — 「‘이웃’이라는 말을 보면 다리보다 사람 이야기를 하고 싶었던 것 같아.」","mis":"K6-2-u1-X06"}],"explanation":["작가의 삶은 읽기를 시작하게 하는 실마리예요.","슬찬과 온새는 삶을 알고 다시 작품의 말로 돌아왔어요.","예강은 삶만 보고 작품 읽기를 멈추었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#1','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',2,'sa','auto','작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것을 무엇이라고 하나요? 「작가의 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":2,"kind":"sa","stem":"작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것을 무엇이라고 하나요? 「작가의 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["의도"],"explanation":["글에는 쓴 사람이 있어요.","쓴 까닭과 바란 것을 작품에 담아요.","이것을 작가의 의도라고 해요."],"mis":"K6-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#2','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C2',2,'mc','auto','시 「창문」에서 두 번 나온 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"시 「창문」에서 두 번 나온 말은 어느 것인가요?","options":[{"t":"같은","correct":true},{"t":"창문 앞에","mis":"K6-2-u1-X03"},{"t":"밤이 되자","mis":"K6-2-u1-X03"},{"t":"바뀐다","mis":"K6-2-u1-X03"}],"explanation":["「같은 유리 / 같은 자리」에 「같은」이 두 번 나와요.","달라진 것이 없다는 것을 힘주어 말해요.","그런데도 보이는 것이 바뀐다는 데에 눈길이 가요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#3','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C3',3,'mc','auto','윤채겸은 나루에서 배를 젓던 사공의 딸이에요. 이것을 알고 「노 젓던 저 물길이 어디로 가겠는가」를 다시 읽었을 때 가장 알맞은 짐작은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X04']::text[],false,'{"seq":3,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"윤채겸은 나루에서 배를 젓던 사공의 딸이에요. 이것을 알고 「노 젓던 저 물길이 어디로 가겠는가」를 다시 읽었을 때 가장 알맞은 짐작은 어느 것인가요?","options":[{"t":"나루에서 이어져 온 삶과 일이 쉽게 사라지지 않기를 바라는 마음","correct":true},{"t":"물길이 어디로 흐르는지 몰라 길을 묻는 마음","mis":"K6-2-u1-X08"},{"t":"사공의 딸이니 무조건 다리에 반대한다는 뜻","mis":"K6-2-u1-X04"},{"t":"노 젓는 방법을 알려 주려는 마음","mis":"K6-2-u1-X08"}],"explanation":["작가는 나루에서 마을 사람들의 사정을 들으며 자랐어요.","「노 젓던 저 물길」은 그 삶을 가리켜요.","「어디로 가겠는가」는 사라지지 않는다는 뜻을 힘주어 말해요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#4','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',3,'ox','auto','같은 시를 읽고 친구와 생각이 다르면 둘 가운데 하나는 틀린 읽기예요.',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":4,"concept":"K6-2-u1-C1","difficulty":3,"kind":"ox","stem":"같은 시를 읽고 친구와 생각이 다르면 둘 가운데 하나는 틀린 읽기예요.","answer":"X","reason_options":[{"t":"둘 다 작품에서 근거를 댔다면 둘 다 좋은 읽기이기 때문에","correct":true},{"t":"작품의 뜻은 하나로 정해져 있기 때문에","mis":"K6-2-u1-X06"}],"mis":"K6-2-u1-X06","explanation":["예강은 「밤마다」, 「오래」를 근거로 외롭게 읽었어요.","슬찬은 「나를 보여 준다」를 근거로 반갑게 읽었어요.","근거가 있으면 서로 달라도 좋은 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#5','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C2',3,'mc','auto','「창문」에서 「밤이 되자 / 나를 보여 준다」가 주는 느낌으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X08']::text[],false,'{"seq":5,"concept":"K6-2-u1-C2","difficulty":3,"kind":"mc","stem":"「창문」에서 「밤이 되자 / 나를 보여 준다」가 주는 느낌으로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻밖의 것을 알아차린 느낌","correct":true},{"t":"한 번이 아니라 되풀이해 온 느낌","mis":"K6-2-u1-X03"},{"t":"창문이 깨질까 봐 걱정되는 느낌","mis":"K6-2-u1-X08"},{"t":"밖이 잘 보여 시원한 느낌","mis":"K6-2-u1-X08"}],"explanation":["낮에는 밖을 보여 주던 창문이에요.","밤이 되자 유리에 내가 비쳐 보여요.","같은 창문에서 뜻밖의 것을 알아차린 느낌이 들어요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#6','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',3,'match','auto','「창문」을 읽은 두 친구의 생각과 그 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u1-C1","difficulty":3,"kind":"match","stem":"「창문」을 읽은 두 친구의 생각과 그 근거를 알맞게 이으세요.","pairs":[{"l":"예강 — 혼자라서 외로운 시","r":"「밤마다」, 「오래 서 있는다」"},{"l":"슬찬 — 드디어 나를 보게 된 반가운 시","r":"「나를 보여 준다」"},{"l":"두 읽기 모두","r":"시에서 근거를 들어 좋은 읽기"}],"mis":"K6-2-u1-X06","explanation":["같은 시를 읽고도 생각이 갈릴 수 있어요.","두 친구 모두 시에 적힌 말을 근거로 댔어요.","근거가 있으면 둘 다 좋은 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#7','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C2',3,'error','auto','「나루를 지켜」의 「백 번」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X06']::text[],false,'{"seq":7,"concept":"K6-2-u1-C2","difficulty":3,"kind":"error","stem":"「나루를 지켜」의 「백 번」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「백 번은 나루를 실제로 고친 횟수를 적은 기록이야.」","correct":true,"mis_target":"K6-2-u1-X03"},{"t":"준희 — 「몇 번이 되어도 지키겠다는 뜻이야.」","mis":"K6-2-u1-X06"},{"t":"이현 — 「같은 말을 되풀이해서 힘을 준 거야.」","mis":"K6-2-u1-X06"}],"explanation":["「백 번」은 두 번 되풀이되어 힘을 주는 말이에요.","실제 횟수가 아니라 「아무리 여러 번이라도」라는 뜻이에요.","서아는 글자 그대로만 받아들였어요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#8','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C3',4,'mc','auto','작가의 삶과 작품 읽기의 관계로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X05','K6-2-u1-X06']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":4,"kind":"mc","stem":"작가의 삶과 작품 읽기의 관계로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작가의 삶을 실마리로 얻고, 다시 작품으로 돌아와 근거를 찾는다","correct":true},{"t":"작가의 삶을 알면 작품은 다시 읽지 않아도 된다","mis":"K6-2-u1-X04"},{"t":"작가의 삶은 작품과 상관없으니 알아보지 않는다","mis":"K6-2-u1-X05"},{"t":"작가의 삶과 다르게 읽으면 틀린 읽기이다","mis":"K6-2-u1-X06"}],"explanation":["작가를 아는 것과 작품을 읽는 것은 둘 다 필요해요.","삶은 실마리, 근거는 작품 안에서 찾아요.","둘 가운데 하나만 쓰면 감상이 얕아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#9','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',4,'mc','auto','두 시조에 담긴 작가의 의도를 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":9,"concept":"K6-2-u1-C1","difficulty":4,"kind":"mc","stem":"두 시조에 담긴 작가의 의도를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"「같이 건너세」 — 마을과 마을이 이어지기를 바람 / 「나루를 지켜」 — 이어져 온 삶을 쉽게 지우지 말자","correct":true},{"t":"「같이 건너세」 — 이어져 온 삶을 쉽게 지우지 말자 / 「나루를 지켜」 — 마을과 마을이 이어지기를 바람","mis":"K6-2-u1-X04"},{"t":"「같이 건너세」 — 나루를 새로 고치자 / 「나루를 지켜」 — 다리를 빨리 놓자","mis":"K6-2-u1-X08"},{"t":"두 시조 모두 — 강을 건너는 일은 위험하다","mis":"K6-2-u1-X02"}],"explanation":["「같이 건너세」의 근거는 「또 한」의 되풀이, 「이웃」, 「한 마을로 살리라」예요.","「나루를 지켜」의 근거는 「백 번」의 되풀이, 「변할 줄이 있으랴」예요.","근거를 들 수 있으면 좋은 짐작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L02_challenge#10','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',4,'essay','teacher','시조 「같이 건너세」와 「나루를 지켜」 가운데 하나를 골라, 작가의 의도를 짐작하고 시조에서 근거가 되는 표현을 두 가지 들어 쓰세요. 작가의 삶이 짐작에 어떻게 도움이 되었는지도 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u1-C1","difficulty":4,"kind":"essay","stem":"시조 「같이 건너세」와 「나루를 지켜」 가운데 하나를 골라, 작가의 의도를 짐작하고 시조에서 근거가 되는 표현을 두 가지 들어 쓰세요. 작가의 삶이 짐작에 어떻게 도움이 되었는지도 한 문장으로 쓰세요.","answer_guide":{"answer":"예(「같이 건너세」): 다리를 놓아 마을과 마을, 사람과 사람이 이어지기를 바라는 마음을 전하려 한 것 같다. 「돌 하나 또 한 돌을」, 「또 한 사람」처럼 「또 한」을 되풀이해 작은 것이 쌓이는 모습을 보여 주었고, 「건너오면 이웃이라」, 「한 마을로 살리라」라고 힘주어 끝맺었기 때문이다. 작가가 다리 놓는 일을 하며 물에 막힌 아이들을 보았다는 것을 알고 나니 「이웃」이라는 말이 사람 이야기로 다시 보였다.","scoring_points":["작가의 의도를 한 문장으로 짐작했는가","시조에서 근거가 되는 표현을 두 가지 들었는가","작가의 삶을 실마리로 쓰고 다시 작품의 말로 돌아왔는가"]},"explanation":["짐작 + 근거를 한 묶음으로 써요.","되풀이한 말과 힘준 끝맺음이 좋은 근거예요.","작가의 삶은 실마리로만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#1','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C2',1,'mc','auto','「돌아오는 길」에서 여러 번 나온 말은 어느 것인가요?',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":1,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"「돌아오는 길」에서 여러 번 나온 말은 어느 것인가요?","options":[{"t":"걷는다","correct":true},{"t":"바다","mis":"K6-2-u1-X02"},{"t":"노래","mis":"K6-2-u1-X02"},{"t":"창문","mis":"K6-2-u1-X02"}],"explanation":["2연 「담을 따라 걷는다」, 4연 「걷는 것이 아니다」, 「길을 내려고 걷는다」예요.","「걷는다」가 되풀이되어 시의 뼈대가 돼요.","바다·노래·창문은 이 시에 없는 말이에요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#2','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',1,'mc','auto','「돌아오는 길」 2연의 「담」과 「닫힌 문」은 무엇을 나타낸다고 볼 수 있나요?',ARRAY['K6-2-u1-X08']::text[],false,'{"seq":2,"concept":"K6-2-u1-C4","difficulty":1,"kind":"mc","stem":"「돌아오는 길」 2연의 「담」과 「닫힌 문」은 무엇을 나타낸다고 볼 수 있나요?","options":[{"t":"나아가려는 사람을 막고 있는 것","correct":true},{"t":"사람이 사는 집의 생김새","mis":"K6-2-u1-X08"},{"t":"누군가 잃어버린 열쇠가 있는 곳","mis":"K6-2-u1-X08"},{"t":"비를 피할 수 있는 곳","mis":"K6-2-u1-X08"}],"explanation":["「담은 길고 문은 닫혀 있다」 — 둘이 나란히 놓였어요.","걷는 사람 앞이 막혀 있는 처지예요.","시어는 겉뜻보다 넓은 뜻을 품어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#3','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',1,'ox','auto','시는 여러 번 읽을수록 처음에는 안 보이던 말이 보이기도 해요.',ARRAY['K6-2-u1-X08']::text[],false,'{"seq":3,"concept":"K6-2-u1-C4","difficulty":1,"kind":"ox","stem":"시는 여러 번 읽을수록 처음에는 안 보이던 말이 보이기도 해요.","answer":"O","reason_options":[{"t":"되풀이해 읽으면 낱말과 연 사이의 관계가 새로 보이기 때문에","correct":true},{"t":"시는 한 번 읽으면 뜻이 모두 드러나기 때문에","mis":"K6-2-u1-X08"}],"mis":"K6-2-u1-X08","explanation":["한 연씩 소리 내어 읽어 보아요.","두 번째 읽을 때 되풀이된 말이 들려요.","여러 번 읽는 것이 감상의 바탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#4','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',1,'sa','auto','「돌아오는 길」은 모두 몇 연인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u1-C4","difficulty":1,"kind":"sa","stem":"「돌아오는 길」은 모두 몇 연인가요? 숫자로 쓰세요.","answer":["4","네"],"explanation":["연은 시에서 한 덩어리로 묶인 줄들이에요.","1연부터 4연까지 있어요.","연마다 걷는 사람의 처지가 조금씩 달라져요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"},"mis":"K6-2-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#5','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',2,'match','auto','시구와 그렇게 읽은 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u1-C4","difficulty":2,"kind":"match","stem":"시구와 그렇게 읽은 근거를 알맞게 이으세요.","pairs":[{"l":"만져지는 것이 없다","r":"앞 줄에서 잃어버린 것을 세어 보았다"},{"l":"하늘만 넓다","r":"담은 길고 문은 닫혀 위밖에 열린 곳이 없다"},{"l":"남은 발자국이 길이 된다","r":"뒤를 돌아본 자리에 남은 것이 있었다"}],"mis":"K6-2-u1-X02","explanation":["시구의 뜻은 그 앞뒤 줄에서 근거를 찾아요.","1연은 잃은 것, 2연은 막힘, 3연은 남은 것이에요.","근거를 들면 짐작이 단단해져요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#6','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C3',2,'mc','auto','문해원은 어릴 때 집을 자주 옮겨 한 학교에 오래 다니지 못했고, 옮길 때마다 낯선 골목을 혼자 걸었으며 짐을 쌀 때마다 무언가를 두고 왔어요. 어른이 되어서는 오래 살 곳을 정하고 같은 골목을 날마다 걸으며 걷는 일에 대한 시를 썼어요. 이것을 알고 다시 읽을 때 새로 보이는 시구와 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":6,"concept":"K6-2-u1-C3","difficulty":2,"kind":"mc","stem":"문해원은 어릴 때 집을 자주 옮겨 한 학교에 오래 다니지 못했고, 옮길 때마다 낯선 골목을 혼자 걸었으며 짐을 쌀 때마다 무언가를 두고 왔어요. 어른이 되어서는 오래 살 곳을 정하고 같은 골목을 날마다 걸으며 걷는 일에 대한 시를 썼어요. 이것을 알고 다시 읽을 때 새로 보이는 시구와 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「잃어버린 것」 — 이사할 때마다 두고 온 것들이 떠올라서","correct":true},{"t":"「하늘」 — 작가가 하늘 사진을 즐겨 찍어서","mis":"K6-2-u1-X02"},{"t":"「담」 — 작가의 집에는 담이 없어서","mis":"K6-2-u1-X02"},{"t":"「발자국」 — 작가가 달리기 선수여서","mis":"K6-2-u1-X02"}],"explanation":["작가는 짐을 쌀 때마다 무언가를 두고 왔어요.","그래서 「잃어버린 것을 세어 본다」가 그냥 나온 말이 아니겠구나 싶어요.","다른 보기는 작가의 삶에 나오지 않는 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#7','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C3',2,'mc','auto','「문해원이 이사를 자주 다녔대. 그러니까 이 시는 이사에 대한 시야. 다 풀렸어.」라고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X05','K6-2-u1-X06']::text[],false,'{"seq":7,"concept":"K6-2-u1-C3","difficulty":2,"kind":"mc","stem":"「문해원이 이사를 자주 다녔대. 그러니까 이 시는 이사에 대한 시야. 다 풀렸어.」라고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"작가의 삶은 실마리일 뿐이야. 시의 어느 줄이 그렇게 읽히는지 근거를 함께 들어야 해.","correct":true},{"t":"맞아. 작가의 삶을 알았으니 이제 시는 더 읽지 않아도 돼.","mis":"K6-2-u1-X04"},{"t":"작가의 삶은 시와 상관없으니 아예 알아보지 않는 게 좋아.","mis":"K6-2-u1-X05"},{"t":"이사가 아니라 여행에 대한 시라고 정해 두자.","mis":"K6-2-u1-X06"}],"explanation":["작가의 삶은 시를 다시 보게 하는 실마리예요.","실마리를 얻은 뒤에는 내가 읽고 느낀 것과 견주어요.","근거는 언제나 시 안에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#8','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',2,'ox','auto','「나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다」에서 「나」는 잃은 것을 찾으려고 걸어요.',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":8,"concept":"K6-2-u1-C4","difficulty":2,"kind":"ox","stem":"「나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다」에서 「나」는 잃은 것을 찾으려고 걸어요.","answer":"X","reason_options":[{"t":"「찾으려고 걷는 것이 아니다」라고 하고 길을 내려고 걷는다고 했기 때문에","correct":true},{"t":"1연에서 잃어버린 것을 세어 보았기 때문에","mis":"K6-2-u1-X02"}],"mis":"K6-2-u1-X02","explanation":["4연은 「~이 아니다」로 앞의 생각을 뒤집어요.","걷는 까닭은 「길을 내려고」예요.","1연만 보고 판단하면 시의 흐름을 놓쳐요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#9','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',2,'mc','auto','「남은 발자국이 길이 된다」를 읽은 것으로 시에서 근거를 댈 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":9,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「남은 발자국이 길이 된다」를 읽은 것으로 시에서 근거를 댈 수 있는 것은 어느 것인가요?","options":[{"t":"걸어온 자국이 다음에 걸을 길이 된다","correct":true},{"t":"발자국이 지저분하게 남아 있다는 불평","mis":"K6-2-u1-X08"},{"t":"길을 잃어서 되돌아가야 한다는 걱정","mis":"K6-2-u1-X02"},{"t":"작가가 발자국 화석을 좋아했다는 뜻","mis":"K6-2-u1-X02"}],"explanation":["3연에서 걸어온 뒤를 돌아보니 발자국이 남아 있어요.","그 발자국이 길이 된다고 했어요.","잃기만 한 것이 아니라 남은 것도 있다는 뜻으로 읽을 수 있어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_basic#10','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C1',3,'mc','auto','시를 읽고 짐작한 작가의 의도를 말하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X06','K6-2-u1-X04']::text[],false,'{"seq":10,"concept":"K6-2-u1-C1","difficulty":3,"kind":"mc","stem":"시를 읽고 짐작한 작가의 의도를 말하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"짐작한 의도와 그 근거가 된 시구를 한 묶음으로 말한다","correct":true},{"t":"근거 없이 느낌만 짧게 말한다","mis":"K6-2-u1-X06"},{"t":"작가의 삶만 말하고 시의 말은 들지 않는다","mis":"K6-2-u1-X04"},{"t":"친구가 말한 짐작을 그대로 따라 한다","mis":"K6-2-u1-X06"}],"explanation":["짐작 + 근거를 한 묶음으로 말하면 다른 사람도 내 짐작을 따라올 수 있어요.","근거는 되풀이된 말이나 힘준 시구에서 찾아요.","작가의 삶은 실마리로 덧붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#1','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C4',2,'sa','auto','시에 쓰인 말을 무엇이라고 하나요? 두 글자로 쓰세요. (예: 「길」, 「담」, 「발자국」)','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C4","difficulty":2,"kind":"sa","stem":"시에 쓰인 말을 무엇이라고 하나요? 두 글자로 쓰세요. (예: 「길」, 「담」, 「발자국」)","answer":["시어"],"explanation":["시에 쓰인 말을 시어라고 해요.","시어는 여러 뜻을 품는 일이 많아요.","「길」은 걷는 길도, 살아가는 날들도 될 수 있어요."],"mis":"K6-2-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#2','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C2',2,'mc','auto','「돌아오는 길」 4연에서 「걷는다」를 되풀이해 쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X17','K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「돌아오는 길」 4연에서 「걷는다」를 되풀이해 쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"걷는 일에 담긴 다짐을 힘주어 드러내려고","correct":true},{"t":"시의 글자 수를 맞추려고","mis":"K6-2-u1-X17"},{"t":"걷기 운동을 하자고 권하려고","mis":"K6-2-u1-X08"},{"t":"작가가 걷는 것을 싫어해서","mis":"K6-2-u1-X02"}],"explanation":["마지막 연에서 「걷는 것이 아니다」, 「걷는다」가 이어져요.","같은 말을 되풀이해 걷는 까닭을 또렷이 해요.","되풀이는 힘을 주는 표현이에요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#3','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C1',3,'error','auto','「길을 내려고 걷는다」를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":3,"concept":"K6-2-u1-C1","difficulty":3,"kind":"error","stem":"「길을 내려고 걷는다」를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지호 — 「둘이 다르게 읽었으니 둘 다 틀렸어. 작가에게 물어봐야 알아.」","correct":true,"mis_target":"K6-2-u1-X06"},{"t":"온새 — 「뒤에 오는 사람이 이 발자국을 밟을 테니 남은 사람들을 위한 말 같아.」","mis":"K6-2-u1-X06"},{"t":"예강 — 「잃은 걸 붙잡지 말고 앞으로 가자는 자기 다짐으로 읽었어.」","mis":"K6-2-u1-X06"}],"explanation":["온새와 예강은 서로 다르게 읽었어요.","두 사람 모두 시에서 근거를 들었어요.","시를 읽는 일에는 맞고 틀림이 아니라 근거가 있고 없음이 있어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#4','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C3',3,'ox','auto','작가의 의도를 짐작한다는 것은 작가가 생각한 대로만 읽어야 한다는 뜻이에요.',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":4,"concept":"K6-2-u1-C3","difficulty":3,"kind":"ox","stem":"작가의 의도를 짐작한다는 것은 작가가 생각한 대로만 읽어야 한다는 뜻이에요.","answer":"X","reason_options":[{"t":"작가의 의도는 실마리이고, 내가 읽고 느낀 것과 견주어 근거가 있으면 좋은 읽기이기 때문에","correct":true},{"t":"작가와 다르게 읽으면 틀린 것이기 때문에","mis":"K6-2-u1-X06"}],"mis":"K6-2-u1-X06","explanation":["짐작하는 것과 그대로 따르는 것은 달라요.","작가의 삶은 다시 보게 하는 실마리예요.","둘이 달라도 근거만 있으면 좋은 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#5','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C4',3,'mc','auto','「닫힌 문 위로 하늘만 넓다」를 그렇게 읽은 근거로 알맞은 것은 어느 것인가요? (하늘만 넓다 = 열린 곳이 위뿐이다)',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":5,"concept":"K6-2-u1-C4","difficulty":3,"kind":"mc","stem":"「닫힌 문 위로 하늘만 넓다」를 그렇게 읽은 근거로 알맞은 것은 어느 것인가요? (하늘만 넓다 = 열린 곳이 위뿐이다)","options":[{"t":"담은 길고 문은 닫혀 있어 열린 곳이 위밖에 없다","correct":true},{"t":"앞 연에서 잃어버린 것을 세어 보았다","mis":"K6-2-u1-X02"},{"t":"뒤를 돌아본 자리에 남은 것이 있었다","mis":"K6-2-u1-X02"},{"t":"비가 그쳐 날씨가 맑았다","mis":"K6-2-u1-X02"}],"explanation":["같은 연의 앞 줄이 근거예요.","옆은 담, 앞은 닫힌 문이에요.","그래서 「하늘만」 넓게 보여요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#6','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C2',3,'mc','auto','「돌아오는 길」 1연과 3연을 견주어 읽을 때 드러나는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X02']::text[],false,'{"seq":6,"concept":"K6-2-u1-C2","difficulty":3,"kind":"mc","stem":"「돌아오는 길」 1연과 3연을 견주어 읽을 때 드러나는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"잃은 것만 있는 줄 알았는데 남은 것도 있다는 마음의 바뀜","correct":true},{"t":"1연과 3연은 서로 상관없는 이야기","mis":"K6-2-u1-X03"},{"t":"잃은 것을 모두 되찾았다는 기쁨","mis":"K6-2-u1-X02"},{"t":"발자국 때문에 길을 잃었다는 걱정","mis":"K6-2-u1-X02"}],"explanation":["1연 — 주머니에 만져지는 것이 없어요.","3연 — 뒤를 돌아보니 발자국이 남아 있어요.","두 연을 나란히 놓으면 마음이 바뀌는 흐름이 보여요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#7','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C4',3,'match','auto','「돌아오는 길」의 시어와 그 시어가 나타낸다고 볼 수 있는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u1-C4","difficulty":3,"kind":"match","stem":"「돌아오는 길」의 시어와 그 시어가 나타낸다고 볼 수 있는 것을 알맞게 이으세요.","pairs":[{"l":"담 · 닫힌 문","r":"나아가려는 사람을 막는 것"},{"l":"하늘","r":"위로 열려 있는 곳"},{"l":"발자국","r":"걸어온 날들이 남긴 자국"}],"mis":"K6-2-u1-X08","explanation":["시어는 겉뜻보다 넓은 뜻을 품어요.","시어가 나온 연에서 걷는 사람의 처지를 보아요.","처지와 이어 읽으면 시어의 뜻이 드러나요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#8','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C3',4,'mc','auto','문해원의 삶(어릴 때 이사를 자주 함 · 어른이 되어 같은 골목을 날마다 걸음)과 시를 함께 읽고 짐작한 의도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":4,"kind":"mc","stem":"문해원의 삶(어릴 때 이사를 자주 함 · 어른이 되어 같은 골목을 날마다 걸음)과 시를 함께 읽고 짐작한 의도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"잃은 것이 있어도 걸어온 자국은 남고, 그 자국이 다음 길이 된다는 것","correct":true},{"t":"이사는 나쁜 일이니 하지 말자는 것","mis":"K6-2-u1-X04"},{"t":"골목길을 깨끗하게 쓰자는 것","mis":"K6-2-u1-X08"},{"t":"잃어버린 물건을 꼭 되찾자는 것","mis":"K6-2-u1-X02"}],"explanation":["작가의 삶은 「잃어버린 것」, 「걷는다」를 다시 보게 해요.","시의 근거는 「남은 발자국이 길이 된다」, 「길을 내려고 걷는다」예요.","삶과 시의 근거가 함께 가리키는 짐작이 가장 단단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#9','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C4',4,'blank','auto','짐작과 근거를 한 묶음으로 쓴 문장을 완성하세요. 「잃은 것이 있어도 걸어온 자국은 남는다는 것을 전하려 한 것 같다. 왜냐하면 (  ) 때문이다.」 빈칸에 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X06','K6-2-u1-X17']::text[],false,'{"seq":9,"concept":"K6-2-u1-C4","difficulty":4,"kind":"blank","stem":"짐작과 근거를 한 묶음으로 쓴 문장을 완성하세요. 「잃은 것이 있어도 걸어온 자국은 남는다는 것을 전하려 한 것 같다. 왜냐하면 (  ) 때문이다.」 빈칸에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「남은 발자국이 길이 된다」라는 시구가 있기","correct":true},{"t":"작가가 유명한 사람이기","mis":"K6-2-u1-X04"},{"t":"내가 이 시를 좋아하기","mis":"K6-2-u1-X06"},{"t":"시가 네 연으로 되어 있기","mis":"K6-2-u1-X17"}],"explanation":["「왜냐하면」 뒤에는 시에서 찾은 근거가 와야 해요.","「남은 발자국이 길이 된다」는 짐작을 바로 받쳐 줘요.","좋아하는 마음이나 연의 수는 근거가 되지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L04_challenge#10','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C4',4,'essay','teacher','「돌아오는 길」에서 짐작한 작가의 의도를 한 문장으로 쓰고, 근거가 되는 시구를 두 가지 드세요. 그리고 작가의 삶을 알고 나서 다르게 보인 시어 하나를 골라 어떻게 다르게 보였는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u1-C4","difficulty":4,"kind":"essay","stem":"「돌아오는 길」에서 짐작한 작가의 의도를 한 문장으로 쓰고, 근거가 되는 시구를 두 가지 드세요. 그리고 작가의 삶을 알고 나서 다르게 보인 시어 하나를 골라 어떻게 다르게 보였는지 쓰세요.","answer_guide":{"answer":"예: 잃은 것이 있어도 걸어온 자국은 남으며 그 자국이 다음 길이 된다는 것을 전하려 한 것 같다. 근거는 「남은 발자국이 길이 된다」와 마지막 연의 「길을 내려고 걷는다」이다. 작가가 어릴 때 이사를 자주 다니며 짐을 쌀 때마다 무언가를 두고 왔다는 것을 알고 나니, 1연의 「잃어버린 것」이 그냥 물건이 아니라 두고 온 학교와 친구처럼 보였다.","scoring_points":["의도를 한 문장으로 짐작했는가","근거 시구를 두 가지 들었는가","작가의 삶과 이어 다르게 보인 시어를 설명했는가"]},"explanation":["의도 + 근거 두 가지를 써요.","작가의 삶은 시어를 다시 보게 하는 실마리예요.","마지막에는 다시 시의 말로 돌아와요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#1','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C5',1,'match','auto','이야기 구조와 설명을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C5","difficulty":1,"kind":"match","stem":"이야기 구조와 설명을 알맞게 이으세요.","pairs":[{"l":"발단","r":"이야기가 시작되는 부분"},{"l":"전개","r":"사건이 본격적으로 생기는 부분"},{"l":"절정","r":"긴장감이 높아지거나 갈등이 두드러지는 부분"},{"l":"결말","r":"이야기가 마무리되는 부분"}],"mis":"K6-2-u1-X09","explanation":["이야기는 시작되고 · 커지고 · 부딪히고 · 마무리되는 차례를 지녀요.","이것을 이야기 구조라고 해요.","발단 → 전개 → 절정 → 결말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#2','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C5',1,'mc','auto','이야기에서 긴장감이 높아지거나 갈등이 두드러지는 부분은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":2,"concept":"K6-2-u1-C5","difficulty":1,"kind":"mc","stem":"이야기에서 긴장감이 높아지거나 갈등이 두드러지는 부분은 어느 것인가요?","options":[{"t":"절정","correct":true},{"t":"발단","mis":"K6-2-u1-X09"},{"t":"전개","mis":"K6-2-u1-X09"},{"t":"결말","mis":"K6-2-u1-X09"}],"explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","긴장감이 가장 높은 곳이 절정이에요.","결말은 이야기가 마무리되는 부분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#3','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C6',1,'mc','auto','「종을 잃은 마을」 둘째 부분에서 일어난 중요한 사건은 어느 것인가요?',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":3,"concept":"K6-2-u1-C6","difficulty":1,"kind":"mc","stem":"「종을 잃은 마을」 둘째 부분에서 일어난 중요한 사건은 어느 것인가요?","options":[{"t":"겨울에 종에 금이 가 마을이 어긋나기 시작했다","correct":true},{"t":"덕곤 할아버지가 종을 팔았다","mis":"K6-2-u1-X02"},{"t":"늘봄이 마을을 떠났다","mis":"K6-2-u1-X02"},{"t":"마을에 시계를 모두 나누어 주었다","mis":"K6-2-u1-X02"}],"explanation":["둘째 부분은 「그해 겨울 어느 새벽, 종에 금이 갔다」로 시작해요.","어른들이 미루는 사이 마을이 어긋났어요.","다른 보기는 이야기에 없는 일이에요."],"asset":{"type":"passage","lines":["그해 겨울 어느 새벽, 종에 금이 갔다.","새 종을 만들려면 큰돈이 든다고 했다.","어른들은 봄에, 다시 여름에 이야기하자며 미루었다.","그사이 마을은 어긋났다. 반만 모이는 날이 잦았고 서로 탓했다."],"title":"「종을 잃은 마을」 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#4','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C6',1,'ox','auto','줄거리를 간추릴 때는 이야기에 나온 모든 문장을 차례대로 옮겨 적어요.',ARRAY['K6-2-u1-X11']::text[],false,'{"seq":4,"concept":"K6-2-u1-C6","difficulty":1,"kind":"ox","stem":"줄거리를 간추릴 때는 이야기에 나온 모든 문장을 차례대로 옮겨 적어요.","answer":"X","reason_options":[{"t":"중요한 사건만 골라 흐름이 이어지게 짧게 적기 때문에","correct":true},{"t":"한 문장이라도 빠지면 줄거리가 틀리기 때문에","mis":"K6-2-u1-X11"}],"mis":"K6-2-u1-X11","explanation":["긴 이야기를 다 외울 수는 없어요.","중요한 사건을 골라 흐름이 이어지게 적어요.","덜 중요한 것은 덜어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#5','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C5',2,'mc','auto','「종을 잃은 마을」에서 긴장감이 가장 높은 곳은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":5,"concept":"K6-2-u1-C5","difficulty":2,"kind":"mc","stem":"「종을 잃은 마을」에서 긴장감이 가장 높은 곳은 어느 것인가요?","options":[{"t":"늘봄이 나무판을 두드리다 나무람을 듣고도 열이레 동안 올라간 곳","correct":true},{"t":"덕곤 할아버지가 새벽마다 종을 울리던 곳","mis":"K6-2-u1-X09"},{"t":"이듬해 봄에 새 종이 걸린 곳","mis":"K6-2-u1-X09"},{"t":"늘봄이 이불 속에서 하나, 둘, 셋을 세던 곳","mis":"K6-2-u1-X09"}],"explanation":["인물이 가장 크게 부딪히고 그만둘까 망설이는 곳을 찾아요.","늘봄은 나무람을 듣고 얼굴이 뜨거워졌지만 다시 올라갔어요.","그래서 셋째 부분이 절정이에요."],"asset":{"type":"passage","lines":["가을 끝 무렵 덕곤 할아버지가 앓아누웠다.","그날 새벽 늘봄은 언덕에 올라 나무판을 두드렸다. 딱, 딱, 딱.","「그게 무슨 종소리냐.」 아랫집 어른이 나와 나무랐다.","늘봄은 얼굴이 뜨거워져 내려왔지만 이튿날 또 올라갔다.","손바닥이 부르터도 열이레 동안 새벽마다 두드렸다."],"title":"「종을 잃은 마을」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#6','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C6',2,'mc','auto','「종을 잃은 마을」의 줄거리를 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11']::text[],false,'{"seq":6,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「종을 잃은 마을」의 줄거리를 잘 간추린 것은 어느 것인가요?","options":[{"t":"종이 깨져 마을이 어긋나자 늘봄이 나무판으로 새벽을 알렸고, 사람들이 다시 모여 새 종을 걸었다","correct":true},{"t":"겨울이었다. 종이 있었다. 아이가 있었다. 눈이 왔다.","mis":"K6-2-u1-X10"},{"t":"산 밑 마을 언덕에 오래된 종이 하나 있었다. 종지기 덕곤 할아버지는 새벽마다…(처음부터 끝까지 그대로)","mis":"K6-2-u1-X11"},{"t":"정말 감동적인 이야기였다.","mis":"K6-2-u1-X11"}],"explanation":["잘 간추린 줄거리는 사건끼리 이어져 있어요.","무슨 일이 왜 일어났는지 알 수 있어요.","늘어놓기·통째 옮기기·느낌만 쓰기는 간추린 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#7','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C5',2,'sa','auto','이야기 구조에서 이야기가 마무리되는 부분을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u1-C5","difficulty":2,"kind":"sa","stem":"이야기 구조에서 이야기가 마무리되는 부분을 두 글자로 쓰세요.","answer":["결말"],"explanation":["발단 — 시작이에요.","전개·절정을 지나요.","이야기가 마무리되는 부분이 결말이에요."],"mis":"K6-2-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#8','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C6',2,'mc','auto','간추린 줄거리가 사건을 늘어놓기만 하면 생기는 문제는 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X16']::text[],false,'{"seq":8,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"간추린 줄거리가 사건을 늘어놓기만 하면 생기는 문제는 어느 것인가요?","options":[{"t":"무슨 일이 왜 일어났는지 알 수 없다","correct":true},{"t":"글이 너무 짧아진다","mis":"K6-2-u1-X10"},{"t":"인물의 이름이 빠진다","mis":"K6-2-u1-X11"},{"t":"시간을 나타내는 말이 없어진다","mis":"K6-2-u1-X16"}],"explanation":["「아이가 나갔다. 비가 왔다. 돌을 옮겼다.」처럼 늘어놓으면","사건 사이의 까닭이 보이지 않아요.","사건을 많이 적는 것보다 이어지게 적는 것이 잘 간추린 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#9','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C5',2,'ox','auto','이야기를 네 부분으로 나눌 때 경계는 언제나 하나로 딱 정해져요.',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":9,"concept":"K6-2-u1-C5","difficulty":2,"kind":"ox","stem":"이야기를 네 부분으로 나눌 때 경계는 언제나 하나로 딱 정해져요.","answer":"X","reason_options":[{"t":"까닭을 말할 수 있으면 전개를 어디부터로 볼지 사람마다 다를 수 있기 때문에","correct":true},{"t":"책에 정답이 적혀 있기 때문에","mis":"K6-2-u1-X09"}],"mis":"K6-2-u1-X09","explanation":["종에 금이 간 곳부터 전개로 볼 수도 있어요.","마을이 어긋나기 시작한 곳부터 전개로 볼 수도 있어요.","중요한 것은 경계를 맞히는 일이 아니라 흐름을 알아보는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_basic#10','kor',6,2,'u1','L07','g6_2_kor_u1_L07_basic','lesson_basic','K6-2-u1-C6',3,'mc','auto','「종을 잃은 마을」 넷째 부분(결말)을 한 문장으로 간추린 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":10,"concept":"K6-2-u1-C6","difficulty":3,"kind":"mc","stem":"「종을 잃은 마을」 넷째 부분(결말)을 한 문장으로 간추린 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"늘봄의 소리에 마을 사람들이 다시 모여 돈을 모았고, 이듬해 봄 새 종이 걸렸다","correct":true},{"t":"새 종이 걸렸다.","mis":"K6-2-u1-X11"},{"t":"눈이 그친 어느 아침 사람들이 모였고 늘봄은 놀라 나무판을 내려놓았고 아랫집 어른이 말했고 그 어른은 화를 냈던 어른이었다.","mis":"K6-2-u1-X11"},{"t":"늘봄이 처음으로 나무판을 두드렸다.","mis":"K6-2-u1-X09"}],"explanation":["결말의 중요한 사건은 사람들이 모여 새 종을 건 일이에요.","「늘봄의 소리에」를 넣어 앞 사건과 이어요.","너무 짧으면 까닭이 빠지고, 너무 길면 통째 옮기기가 돼요."],"asset":{"type":"passage","lines":["눈이 그친 어느 아침, 언덕에 사람들이 모여 있었다.","「네 소리 듣고 나온 지 벌써 여러 날이다.」","처음에 나무랐던 아랫집 어른의 말이었다.","그날 마을 사람들은 돈을 모으기로 했다.","이듬해 봄 새 종이 걸렸고, 첫 소리는 늘봄이 울렸다."],"title":"「종을 잃은 마을」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#1','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C5',2,'sa','auto','이야기 구조에서 이야기가 시작되는 부분을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C5","difficulty":2,"kind":"sa","stem":"이야기 구조에서 이야기가 시작되는 부분을 두 글자로 쓰세요.","answer":["발단"],"explanation":["이야기는 발단에서 시작해요.","인물과 배경이 소개되는 곳이 많아요.","「종을 잃은 마을」에서는 종소리에 맞추어 하루를 시작하는 마을이 나와요."],"mis":"K6-2-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#2','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',2,'mc','auto','「종을 잃은 마을」 셋째 부분에서 중요한 사건으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11']::text[],false,'{"seq":2,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「종을 잃은 마을」 셋째 부분에서 중요한 사건으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아무도 종을 울리지 못하게 되자 늘봄이 나무판을 두드려 새벽을 알리기 시작했다","correct":true},{"t":"늘봄의 손바닥이 부르텄다","mis":"K6-2-u1-X11"},{"t":"아랫집 어른이 나와 나무랐다","mis":"K6-2-u1-X11"},{"t":"헛간에 마른 나무판이 있었다","mis":"K6-2-u1-X11"}],"explanation":["부분마다 이야기의 흐름을 바꾸는 사건을 골라요.","손바닥·나무람·나무판은 그 사건에 딸린 내용이에요.","중심 사건 하나에 「왜」를 붙여 적어요."],"asset":{"type":"passage","lines":["가을 끝 무렵 덕곤 할아버지가 앓아누웠다.","그날 새벽 늘봄은 언덕에 올라 나무판을 두드렸다. 딱, 딱, 딱.","「그게 무슨 종소리냐.」 아랫집 어른이 나와 나무랐다.","늘봄은 얼굴이 뜨거워져 내려왔지만 이튿날 또 올라갔다.","손바닥이 부르터도 열이레 동안 새벽마다 두드렸다."],"title":"「종을 잃은 마을」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#3','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C5',3,'error','auto','「종을 잃은 마을」의 전개가 어디부터인지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X06']::text[],false,'{"seq":3,"concept":"K6-2-u1-C5","difficulty":3,"kind":"error","stem":"「종을 잃은 마을」의 전개가 어디부터인지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「전개가 어디부터인지는 정답이 하나뿐이니 둘 가운데 하나는 틀렸어.」","correct":true,"mis_target":"K6-2-u1-X09"},{"t":"준희 — 「종에 금이 간 곳부터 전개야. 사건이 그때 생겼거든.」","mis":"K6-2-u1-X06"},{"t":"이현 — 「마을이 어긋나기 시작한 곳부터 전개야. 진짜 문제는 그때 생겼거든.」","mis":"K6-2-u1-X06"}],"explanation":["준희와 이현은 서로 다른 곳을 골랐어요.","둘 다 까닭을 말했어요.","경계는 까닭을 말할 수 있으면 사람마다 달라도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#4','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C7',3,'mc','auto','아랫집 어른이 「네 소리 듣고 나온 지 벌써 여러 날이다.」라고 했어요. 이 어른의 마음이 바뀐 것을 알 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12','K6-2-u1-X02']::text[],false,'{"seq":4,"concept":"K6-2-u1-C7","difficulty":3,"kind":"mc","stem":"아랫집 어른이 「네 소리 듣고 나온 지 벌써 여러 날이다.」라고 했어요. 이 어른의 마음이 바뀐 것을 알 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"처음에는 「그게 무슨 종소리냐.」 하며 나무랐던 어른이기 때문에","correct":true},{"t":"어른이 종을 만드는 사람이기 때문에","mis":"K6-2-u1-X12"},{"t":"늘봄의 아버지이기 때문에","mis":"K6-2-u1-X02"},{"t":"그날 눈이 그쳤기 때문에","mis":"K6-2-u1-X12"}],"explanation":["셋째 부분에서 이 어른은 늘봄을 나무랐어요.","넷째 부분에서는 그 소리에 맞추어 나왔다고 말해요.","앞뒤 말을 견주면 마음이 바뀐 것을 알 수 있어요."],"asset":{"type":"passage","lines":["눈이 그친 어느 아침, 언덕에 사람들이 모여 있었다.","「네 소리 듣고 나온 지 벌써 여러 날이다.」","처음에 나무랐던 아랫집 어른의 말이었다.","그날 마을 사람들은 돈을 모으기로 했다.","이듬해 봄 새 종이 걸렸고, 첫 소리는 늘봄이 울렸다."],"title":"「종을 잃은 마을」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#5','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',3,'ox','auto','「종을 잃은 마을」을 「늘봄이 종을 울렸다.」 한 문장으로 간추리면 잘 간추린 거예요.',ARRAY['K6-2-u1-X11']::text[],false,'{"seq":5,"concept":"K6-2-u1-C6","difficulty":3,"kind":"ox","stem":"「종을 잃은 마을」을 「늘봄이 종을 울렸다.」 한 문장으로 간추리면 잘 간추린 거예요.","answer":"X","reason_options":[{"t":"종이 깨짐 → 마을이 어긋남 → 나무판 → 새 종으로 이어지는 중요한 사건이 빠져 뭉뚱그려졌기 때문에","correct":true},{"t":"문장이 짧을수록 잘 간추린 것이기 때문에","mis":"K6-2-u1-X11"}],"mis":"K6-2-u1-X11","explanation":["사건만 고르고 흐름을 잇지 않으면 나열이 돼요.","흐름만 말하고 사건을 고르지 않으면 뭉뚱그림이 돼요.","부분마다 중요한 사건 하나씩, 이어지게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#6','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C5',3,'match','auto','이야기 구조와 「종을 잃은 마을」의 사건을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u1-C5","difficulty":3,"kind":"match","stem":"이야기 구조와 「종을 잃은 마을」의 사건을 알맞게 이으세요.","pairs":[{"l":"발단","r":"종소리에 맞추어 마을이 하루를 시작했다"},{"l":"전개","r":"종에 금이 가고 마을이 어긋났다"},{"l":"절정","r":"늘봄이 나무람을 듣고도 나무판을 두드렸다"},{"l":"결말","r":"사람들이 돈을 모아 새 종을 걸었다"}],"mis":"K6-2-u1-X09","explanation":["발단은 처음 모습, 전개는 문제가 생기는 곳이에요.","절정은 늘봄이 가장 크게 부딪히는 곳이에요.","결말에서 문제가 풀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#7','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',3,'mc','auto','줄거리를 간추리는 차례 가운데 「간추린 문장을 이어 읽어 보고 말이 되는지 확인한다」는 몇째 단계인가요?',ARRAY['K6-2-u1-X10']::text[],false,'{"seq":7,"concept":"K6-2-u1-C6","difficulty":3,"kind":"mc","stem":"줄거리를 간추리는 차례 가운데 「간추린 문장을 이어 읽어 보고 말이 되는지 확인한다」는 몇째 단계인가요?","options":[{"t":"넷째","correct":true},{"t":"첫째","mis":"K6-2-u1-X10"},{"t":"둘째","mis":"K6-2-u1-X10"},{"t":"셋째","mis":"K6-2-u1-X10"}],"explanation":["① 네 부분으로 나누기 ② 부분마다 중요한 사건 고르기","③ 고른 사건을 이어지도록 한두 문장으로 적기","④ 이어 읽어 말이 되는지 확인하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#8','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',4,'mc','auto','「없어지고 나서야 그 값을 알게 된 것」이라는 이 이야기의 흐름을 줄거리에 살린 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X02','K6-2-u1-X11']::text[],false,'{"seq":8,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「없어지고 나서야 그 값을 알게 된 것」이라는 이 이야기의 흐름을 줄거리에 살린 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"종이 깨지자 마을이 어긋났고, 그제야 사람들은 종소리가 마을을 하나로 맞춰 주고 있었음을 알았다","correct":true},{"t":"종은 오래되어 금이 가기 쉬웠다.","mis":"K6-2-u1-X10"},{"t":"마을 사람들은 시계를 사기로 했다.","mis":"K6-2-u1-X02"},{"t":"늘봄은 종소리를 좋아해서 하나, 둘, 셋을 세었다.","mis":"K6-2-u1-X11"}],"explanation":["이야기의 흐름은 「없어짐 → 어긋남 → 값을 앎」이에요.","이 흐름을 잇는 사건이 종이 깨지고 마을이 어긋난 일이에요.","덜 중요한 것이나 이야기에 없는 일은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#9','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',4,'blank','auto','「종이 깨져 마을이 어긋나자 (  ) 사람들이 다시 모여 새 종을 만들었다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X09','K6-2-u1-X11']::text[],false,'{"seq":9,"concept":"K6-2-u1-C6","difficulty":4,"kind":"blank","stem":"「종이 깨져 마을이 어긋나자 (  ) 사람들이 다시 모여 새 종을 만들었다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?","options":[{"t":"늘봄이 나무판을 두드려 새벽을 알렸고, 그 소리에 맞추어","correct":true},{"t":"겨울이 와서 눈이 많이 내렸고,","mis":"K6-2-u1-X10"},{"t":"덕곤 할아버지가 새벽마다 종을 울렸고,","mis":"K6-2-u1-X09"},{"t":"늘봄은 이불 속에서 셋을 세었고,","mis":"K6-2-u1-X11"}],"explanation":["빈칸은 전개와 결말 사이 — 절정의 사건이 들어가요.","「그 소리에 맞추어」가 결말과 이어 줘요.","발단의 일이나 덜 중요한 일은 흐름을 끊어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L07_challenge#10','kor',6,2,'u1','L07','g6_2_kor_u1_L07_challenge','lesson_challenge','K6-2-u1-C6',4,'essay','teacher','「종을 잃은 마을」을 발단·전개·절정·결말로 나누어 부분마다 한 문장씩 간추리고, 네 문장이 이어지도록 이음말을 넣어 다시 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u1-C6","difficulty":4,"kind":"essay","stem":"「종을 잃은 마을」을 발단·전개·절정·결말로 나누어 부분마다 한 문장씩 간추리고, 네 문장이 이어지도록 이음말을 넣어 다시 써 보세요.","answer_guide":{"answer":"예: 발단 — 산 밑 마을 사람들은 덕곤 할아버지의 종소리에 맞추어 하루를 시작했다. 전개 — 그런데 겨울에 종에 금이 가고 새 종 만들기를 미루는 사이 마을이 어긋났다. 절정 — 할아버지마저 앓아눕자 늘봄이 나무판을 두드려 새벽을 알렸고, 나무람을 듣고도 열이레 동안 그만두지 않았다. 결말 — 그 소리에 다시 모인 사람들이 돈을 모았고 이듬해 봄 새 종이 걸렸다.","scoring_points":["네 부분으로 나누었는가","부분마다 중요한 사건을 한 문장으로 골랐는가","「그런데·~자·그 소리에」처럼 사건이 이어지게 썼는가"]},"explanation":["부분마다 중요한 사건 하나씩이에요.","이음말로 까닭과 흐름을 이어요.","네 문장을 이어 읽어 말이 되는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#1','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',1,'mc','auto','「사흘 걸린 다리」에 나오는 「징검다리」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":1,"concept":"K6-2-u1-C7","difficulty":1,"kind":"mc","stem":"「사흘 걸린 다리」에 나오는 「징검다리」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"물 위에 돌을 띄엄띄엄 놓아 건너다니게 만든 다리","correct":true},{"t":"나무로 길게 이어 만든 다리","mis":"K6-2-u1-X15"},{"t":"배를 여러 척 이어 만든 다리","mis":"K6-2-u1-X15"},{"t":"높은 곳에 매단 출렁다리","mis":"K6-2-u1-X15"}],"explanation":["「냇물은 깊지 않아서, 사람들은 징검다리를 밟고 건너다녔습니다.」","돌 열두 개를 하나씩 세며 건넜다고 했어요.","앞뒤 문장이 낱말의 뜻을 알려 줘요."],"asset":{"type":"passage","lines":["냇물 건너에 할머니의 밭이 있었다.","사람들은 징검다리를 밟고 냇물을 건너다녔다.","태건은 방학이면 할머니를 따라 돌 열두 개를 세며 건넜다.","여덟 번째 돌은 흔들려서, 할머니는 늘 그 앞에서 멈추었다."],"title":"「사흘 걸린 다리」 하나"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#2','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C6',1,'mc','auto','「사흘 걸린 다리」 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":2,"concept":"K6-2-u1-C6","difficulty":1,"kind":"mc","stem":"「사흘 걸린 다리」 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰비에 징검돌이 떠내려갔다","correct":true},{"t":"할머니가 밭을 팔았다","mis":"K6-2-u1-X02"},{"t":"어른들이 처음부터 함께 나와 돌을 옮겼다","mis":"K6-2-u1-X02"},{"t":"다리 대신 배를 띄웠다","mis":"K6-2-u1-X02"}],"explanation":["둘째 부분에 큰비로 징검돌이 떠내려간 일이 나와요.","어른들은 처음에는 가을로 미루었어요.","이야기에 적힌 일만 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#3','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',1,'sa','auto','「사흘 걸린 다리」에서 지난여름 큰비는 며칠 동안 내렸나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u1-C7","difficulty":1,"kind":"sa","stem":"「사흘 걸린 다리」에서 지난여름 큰비는 며칠 동안 내렸나요? 두 글자로 쓰세요.","answer":["사흘","3일","삼일"],"explanation":["「지난여름 큰비가 사흘 동안 내려」예요.","사흘은 세 날이에요.","시간을 나타내는 말은 일의 차례를 알려 줘요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","어른들은 바쁜 철이니 가을에 놓자고 미루었다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","여름내 할머니의 걸음은 눈에 띄게 느려졌다."],"title":"「사흘 걸린 다리」 둘"},"mis":"K6-2-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#4','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',1,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u1-C7","difficulty":1,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"지게","r":"짐을 얹어 등에 지는 나무 도구"},{"l":"거들다","r":"남이 하는 일을 옆에서 도와주다"},{"l":"여름내","r":"여름 한철 동안 내내"},{"l":"한나절","r":"하루 낮의 절반쯤 되는 동안"}],"mis":"K6-2-u1-X15","explanation":["낱말이 나온 문장을 떠올려요.","「지게를 지고」, 「거드는 사람도 없었다」, 「여름내」, 「돌 하나에 한나절」이에요.","앞뒤 문장이 뜻을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#5','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',2,'mc','auto','젖은 모래밭에 주저앉은 태건의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":5,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"젖은 모래밭에 주저앉은 태건의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"애써 한 일이 무너지고 혼자라는 생각이 든 막막한 마음","correct":true},{"t":"비가 와서 쉬게 되어 홀가분한 마음","mis":"K6-2-u1-X12"},{"t":"할머니가 도와주지 않아 서운하고 미운 마음","mis":"K6-2-u1-X12"},{"t":"돌이 많아져서 신나는 마음","mis":"K6-2-u1-X12"}],"explanation":["바로 앞에 사흘 쌓은 돌이 비에 흩어졌어요.","거드는 사람도 없이 혼자였어요.","앞뒤 사건이 인물의 마음을 짐작하는 근거예요."],"asset":{"type":"passage","lines":["어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」"],"title":"「사흘 걸린 다리」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#6','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',2,'mc','auto','「지난여름」, 「여름내」, 「사흘째 되던 날」, 「이튿날 아침」 같은 말은 무엇을 나타내나요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":6,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「지난여름」, 「여름내」, 「사흘째 되던 날」, 「이튿날 아침」 같은 말은 무엇을 나타내나요?","options":[{"t":"시간","correct":true},{"t":"장소","mis":"K6-2-u1-X16"},{"t":"인물의 기분","mis":"K6-2-u1-X16"},{"t":"날씨","mis":"K6-2-u1-X16"}],"explanation":["이 말들은 언제 일이 일어났는지 알려 줘요.","시간을 나타내는 표현으로 지난 일과 지금 일을 가려 읽어요.","줄거리를 간추릴 때 일의 차례를 지키는 데 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#7','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C5',2,'mc','auto','태건이 사흘 동안 쌓은 돌이 무너진 날 상우 아저씨가 나타난 부분은 이야기 구조에서 어디인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":7,"concept":"K6-2-u1-C5","difficulty":2,"kind":"mc","stem":"태건이 사흘 동안 쌓은 돌이 무너진 날 상우 아저씨가 나타난 부분은 이야기 구조에서 어디인가요?","options":[{"t":"절정","correct":true},{"t":"발단","mis":"K6-2-u1-X09"},{"t":"전개","mis":"K6-2-u1-X09"},{"t":"결말","mis":"K6-2-u1-X09"}],"explanation":["태건이 가장 크게 부딪히고 주저앉은 곳이에요.","그때 흐름이 바뀌어요.","긴장감이 가장 높은 이곳이 절정이에요."],"asset":{"type":"passage","lines":["어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」"],"title":"「사흘 걸린 다리」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#8','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C6',2,'ox','auto','「태건이 돌을 옮겼다. 비가 왔다. 아저씨가 왔다. 다리를 놓았다.」는 사건이 서로 이어지게 잘 간추린 거예요.',ARRAY['K6-2-u1-X10']::text[],false,'{"seq":8,"concept":"K6-2-u1-C6","difficulty":2,"kind":"ox","stem":"「태건이 돌을 옮겼다. 비가 왔다. 아저씨가 왔다. 다리를 놓았다.」는 사건이 서로 이어지게 잘 간추린 거예요.","answer":"X","reason_options":[{"t":"사건을 늘어놓기만 해서 왜 그런 일이 일어났는지가 드러나지 않기 때문에","correct":true},{"t":"사건을 차례대로 다 적었기 때문에","mis":"K6-2-u1-X10"}],"mis":"K6-2-u1-X10","explanation":["사건 사이에 까닭이 없어요.","「할머니가 먼 길을 돌아다니자」, 「쌓은 돌이 무너진 날」처럼 이어 주는 말이 필요해요.","이어지게 적어야 잘 간추린 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#9','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C7',2,'mc','auto','「이튿날 아침 나가 보니 쌓아 둔 돌이 흩어져 있었다」에서 「이튿날」은 어느 날의 다음 날인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":9,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「이튿날 아침 나가 보니 쌓아 둔 돌이 흩어져 있었다」에서 「이튿날」은 어느 날의 다음 날인가요?","options":[{"t":"다시 비가 온 사흘째 되던 날","correct":true},{"t":"큰비가 그친 날","mis":"K6-2-u1-X16"},{"t":"할머니가 다리를 건넌 날","mis":"K6-2-u1-X16"},{"t":"어른 여섯이 나온 날","mis":"K6-2-u1-X16"}],"explanation":["「사흘째 되던 날 다시 비가 왔고」 바로 뒤에 나와요.","이튿날은 그다음 날이에요.","시간을 나타내는 말이 일의 차례를 알려 줘요."],"asset":{"type":"passage","lines":["어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」"],"title":"「사흘 걸린 다리」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_basic#10','kor',6,2,'u1','L09','g6_2_kor_u1_L09_basic','lesson_basic','K6-2-u1-C6',3,'mc','auto','「사흘 걸린 다리」의 결말을 간추린 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":10,"concept":"K6-2-u1-C6","difficulty":3,"kind":"mc","stem":"「사흘 걸린 다리」의 결말을 간추린 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"이튿날 어른들이 함께 나와 다리를 놓았고, 할머니는 새 돌을 밟으며 멈추지 않고 건넜다","correct":true},{"t":"다리가 놓였다.","mis":"K6-2-u1-X11"},{"t":"태건이 혼자 돌을 굴려 올리기 시작했다.","mis":"K6-2-u1-X09"},{"t":"냇물 건너에 할머니의 밭이 있었다.","mis":"K6-2-u1-X09"}],"explanation":["결말에서는 문제가 풀려요 — 다리가 다시 놓였어요.","할머니가 멈추지 않고 건넌 것이 마무리예요.","너무 짧으면 흐름이 빠지고, 다른 부분의 사건은 결말이 아니에요."],"asset":{"type":"passage","lines":["그다음 날 아침 냇가에 어른 여섯이 나와 있었다.","해가 지기 전에 징검다리가 다시 놓였다.","돌은 열두 개가 아니라 열네 개였다.","할머니는 여덟 번째 돌에서 한 번 멈추었다가,","이번에는 멈추지 않고 건너갔다."],"title":"「사흘 걸린 다리」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#1','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',2,'sa','auto','「사흘 걸린 다리」에서 징검다리를 다시 놓았을 때 돌은 모두 몇 개였나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C7","difficulty":2,"kind":"sa","stem":"「사흘 걸린 다리」에서 징검다리를 다시 놓았을 때 돌은 모두 몇 개였나요? 숫자로 쓰세요.","answer":["14","열네"],"explanation":["「돌은 열두 개가 아니라 열네 개였다.」","처음보다 두 개 더 놓였어요.","작은 말 하나가 장면의 뜻을 바꾸기도 해요."],"asset":{"type":"passage","lines":["그다음 날 아침 냇가에 어른 여섯이 나와 있었다.","해가 지기 전에 징검다리가 다시 놓였다.","돌은 열두 개가 아니라 열네 개였다.","할머니는 여덟 번째 돌에서 한 번 멈추었다가,","이번에는 멈추지 않고 건너갔다."],"title":"「사흘 걸린 다리」 넷"},"mis":"K6-2-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#2','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C6',2,'mc','auto','「사흘 걸린 다리」의 전개를 간추린 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X09']::text[],false,'{"seq":2,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「사흘 걸린 다리」의 전개를 간추린 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰비에 징검돌이 떠내려갔지만 어른들이 가을로 미루자, 할머니는 여름내 한 시간을 돌아 밭에 다녔다","correct":true},{"t":"비가 왔다. 돌이 없었다. 길이 멀었다.","mis":"K6-2-u1-X10"},{"t":"태건은 방학이면 할머니를 따라 돌 열두 개를 세며 건넜다.","mis":"K6-2-u1-X09"},{"t":"할머니가 새 다리를 건넜다.","mis":"K6-2-u1-X09"}],"explanation":["전개는 사건이 본격적으로 생기는 부분이에요.","징검돌이 떠내려가고 어른들이 미루었어요.","그 때문에 할머니가 먼 길을 돌아다녔어요 — 까닭이 이어져요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","어른들은 바쁜 철이니 가을에 놓자고 미루었다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","여름내 할머니의 걸음은 눈에 띄게 느려졌다."],"title":"「사흘 걸린 다리」 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#3','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',3,'error','auto','「사흘 걸린 다리」에서 인상 깊었던 곳을 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":3,"concept":"K6-2-u1-C7","difficulty":3,"kind":"error","stem":"「사흘 걸린 다리」에서 인상 깊었던 곳을 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서아 — 「인상 깊은 곳은 누구나 같아야 하니까 온새가 틀렸어.」","correct":true,"mis_target":"K6-2-u1-X06"},{"t":"예강 — 「상우 아저씨가 ‘나도 좀 하자’라고 한 곳. 도와준다는 말보다 그 말이 더 좋았어.」","mis":"K6-2-u1-X06"},{"t":"온새 — 「마지막 줄. 할머니가 멈추지 않고 건너간 게 다 나은 것 같았어.」","mis":"K6-2-u1-X06"}],"explanation":["인상 깊은 곳은 저마다 달라요.","중요한 것은 장면이 아니라 그렇게 생각한 까닭이에요.","예강과 온새는 까닭을 들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#4','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',3,'mc','auto','할머니가 「여덟 번째 돌에서 한 번 멈추었다가, 이번에는 멈추지 않고 건너갔다」에서 짐작할 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12','K6-2-u1-X02']::text[],false,'{"seq":4,"concept":"K6-2-u1-C7","difficulty":3,"kind":"mc","stem":"할머니가 「여덟 번째 돌에서 한 번 멈추었다가, 이번에는 멈추지 않고 건너갔다」에서 짐작할 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"새 다리가 튼튼하게 놓였고, 할머니의 걸음과 마음도 가벼워졌다","correct":true},{"t":"여덟 번째 돌이 또 흔들렸다","mis":"K6-2-u1-X12"},{"t":"할머니가 다리를 건너기 싫어졌다","mis":"K6-2-u1-X12"},{"t":"돌이 열두 개뿐이었다","mis":"K6-2-u1-X02"}],"explanation":["처음에 여덟 번째 돌은 흔들려서 할머니가 늘 멈추었어요.","이번에는 한 번 멈추었다가 멈추지 않고 건넜어요.","처음 장면과 견주면 달라진 것이 보여요."],"asset":{"type":"passage","lines":["그다음 날 아침 냇가에 어른 여섯이 나와 있었다.","해가 지기 전에 징검다리가 다시 놓였다.","돌은 열두 개가 아니라 열네 개였다.","할머니는 여덟 번째 돌에서 한 번 멈추었다가,","이번에는 멈추지 않고 건너갔다."],"title":"「사흘 걸린 다리」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#5','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',3,'mc','auto','상우 아저씨가 「혼자 사흘을 했다며. 나도 좀 하자.」라고 한 말에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":5,"concept":"K6-2-u1-C7","difficulty":3,"kind":"mc","stem":"상우 아저씨가 「혼자 사흘을 했다며. 나도 좀 하자.」라고 한 말에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"태건이 혼자 애쓴 것을 알아주고 함께하겠다는 마음","correct":true},{"t":"태건이 일을 못해서 대신해 주겠다는 마음","mis":"K6-2-u1-X12"},{"t":"태건에게 그만두라고 나무라는 마음","mis":"K6-2-u1-X12"},{"t":"돌을 가져가려는 마음","mis":"K6-2-u1-X12"}],"explanation":["「혼자 사흘을 했다며」 — 태건의 수고를 알고 있었어요.","「나도 좀 하자」 — 도와준다기보다 함께하겠다는 말이에요.","그다음 날 어른 여섯이 나온 것과도 이어져요."],"asset":{"type":"passage","lines":["어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」"],"title":"「사흘 걸린 다리」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#6','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C5',3,'match','auto','이야기 구조와 「사흘 걸린 다리」의 간추린 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u1-C5","difficulty":3,"kind":"match","stem":"이야기 구조와 「사흘 걸린 다리」의 간추린 내용을 알맞게 이으세요.","pairs":[{"l":"발단","r":"징검다리를 밟고 할머니 밭에 다녔다"},{"l":"전개","r":"돌이 떠내려가 먼 길로 돌아다녔다"},{"l":"절정","r":"혼자 쌓은 돌이 무너진 날 거들 사람이 왔다"},{"l":"결말","r":"여럿이 나와 다리를 다시 놓았다"}],"mis":"K6-2-u1-X09","explanation":["「그러나」, 「그때」처럼 흐름이 꺾이는 말을 살펴요.","절정은 태건이 주저앉은 날이에요.","결말에서 다리가 다시 놓여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#7','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',3,'ox','auto','「돌은 열두 개가 아니라 열네 개였다」는 처음보다 다리가 더 넉넉하게 놓였음을 짐작하게 해요.',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":7,"concept":"K6-2-u1-C7","difficulty":3,"kind":"ox","stem":"「돌은 열두 개가 아니라 열네 개였다」는 처음보다 다리가 더 넉넉하게 놓였음을 짐작하게 해요.","answer":"O","reason_options":[{"t":"처음 다리보다 돌이 두 개 더 놓였다고 했기 때문에","correct":true},{"t":"할머니가 돌을 셀 줄 몰랐기 때문에","mis":"K6-2-u1-X12"}],"mis":"K6-2-u1-X12","explanation":["처음 다리는 돌 열두 개였어요.","여럿이 함께 놓으니 열네 개가 되었어요.","작은 차이가 함께한 힘을 보여 줘요."],"asset":{"type":"passage","lines":["그다음 날 아침 냇가에 어른 여섯이 나와 있었다.","해가 지기 전에 징검다리가 다시 놓였다.","돌은 열두 개가 아니라 열네 개였다.","할머니는 여덟 번째 돌에서 한 번 멈추었다가,","이번에는 멈추지 않고 건너갔다."],"title":"「사흘 걸린 다리」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#8','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C6',4,'mc','auto','「사흘 걸린 다리」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X02']::text[],false,'{"seq":8,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「사흘 걸린 다리」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"큰비에 징검다리가 떠내려가 할머니가 먼 길을 돌아다니자 태건이 혼자 돌을 옮기기 시작했다. 쌓은 돌이 무너진 날 상우 아저씨가 거들었고, 이튿날 마을 어른들이 함께 다리를 다시 놓았다.","correct":true},{"t":"태건이 있었다. 할머니가 있었다. 돌이 있었다. 비가 왔다.","mis":"K6-2-u1-X10"},{"t":"태건은 돌을 옮겼다. 정말 대단한 아이다.","mis":"K6-2-u1-X11"},{"t":"징검다리는 물 위에 돌을 놓은 다리이다. 지게는 짐을 지는 도구이다.","mis":"K6-2-u1-X02"}],"explanation":["두 문장 안에 발단·전개·절정·결말의 중요한 사건이 다 들어가요.","「~자」, 「~날」로 사건이 이어져요.","느낌이나 낱말 뜻은 줄거리가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#9','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C7',4,'blank','auto','「(  ) 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.」 빈칸에 들어갈 시간을 나타내는 표현으로 이야기와 맞는 것은 어느 것인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":9,"concept":"K6-2-u1-C7","difficulty":4,"kind":"blank","stem":"「(  ) 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.」 빈칸에 들어갈 시간을 나타내는 표현으로 이야기와 맞는 것은 어느 것인가요?","options":[{"t":"지난여름","correct":true},{"t":"이듬해 봄","mis":"K6-2-u1-X16"},{"t":"사흘째 되던 날","mis":"K6-2-u1-X16"},{"t":"그다음 날 아침","mis":"K6-2-u1-X16"}],"explanation":["이야기는 「지난여름」에 큰비가 내렸다고 해요.","「사흘째 되던 날」은 태건이 돌을 옮긴 지 사흘째예요.","시간 표현을 바꾸면 일의 차례가 뒤엉켜요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","어른들은 바쁜 철이니 가을에 놓자고 미루었다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","여름내 할머니의 걸음은 눈에 띄게 느려졌다."],"title":"「사흘 걸린 다리」 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L09_challenge#10','kor',6,2,'u1','L09','g6_2_kor_u1_L09_challenge','lesson_challenge','K6-2-u1-C6',4,'essay','teacher','「사흘 걸린 다리」를 네 부분으로 나누어 부분마다 한 문장씩 간추리세요. 그리고 간추릴 때 도움이 된 시간을 나타내는 표현을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u1-C6","difficulty":4,"kind":"essay","stem":"「사흘 걸린 다리」를 네 부분으로 나누어 부분마다 한 문장씩 간추리세요. 그리고 간추릴 때 도움이 된 시간을 나타내는 표현을 두 가지 쓰세요.","answer_guide":{"answer":"예: 발단 — 태건은 방학이면 할머니를 따라 징검다리를 건너 밭에 다녔다. 전개 — 지난여름 큰비에 징검돌이 떠내려가고 어른들이 가을로 미루자, 할머니는 여름내 먼 길을 돌아다녔다. 절정 — 태건이 혼자 돌을 옮기다 사흘째 비에 무너졌을 때 상우 아저씨가 지게를 지고 왔다. 결말 — 그다음 날 어른들이 함께 나와 다리를 다시 놓았고, 할머니는 멈추지 않고 건넜다. 도움이 된 시간 표현: 「지난여름」, 「사흘째 되던 날」(「여름내」, 「이튿날」, 「그다음 날」도 됨).","scoring_points":["네 부분으로 나누어 중요한 사건을 한 문장씩 썼는가","사건이 까닭으로 이어지게 썼는가","시간을 나타내는 표현을 두 가지 들었는가"]},"explanation":["부분마다 중요한 사건 하나씩 — 네 문장이에요.","「~자」, 「그때」로 흐름을 이어요.","시간 표현은 일의 차례를 지켜 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#1','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',1,'match','auto','작품 소개하는 글의 짜임과 넣을 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C8","difficulty":1,"kind":"match","stem":"작품 소개하는 글의 짜임과 넣을 내용을 알맞게 이으세요.","pairs":[{"l":"처음","r":"작품 제목 · 작가 · 이 작품을 고른 까닭"},{"l":"가운데","r":"간추린 줄거리와 짐작한 작가의 의도"},{"l":"끝","r":"읽고 난 내 생각과 권하고 싶은 사람"}],"mis":"K6-2-u1-X11","explanation":["듣는 사람은 무엇에 대한 작품인지부터 알아야 해요.","가운데에는 이 단원에서 배운 두 가지 — 줄거리와 의도 — 가 들어가요.","끝에는 내 생각과 권할 사람을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#2','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',1,'mc','auto','작품을 소개하는 글에 넣으면 좋은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":2,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"작품을 소개하는 글에 넣으면 좋은 것은 어느 것인가요?","options":[{"t":"간추린 줄거리","correct":true},{"t":"책값과 쪽수","mis":"K6-2-u1-X13"},{"t":"결말까지 이야기 전체를 그대로 옮긴 것","mis":"K6-2-u1-X11"},{"t":"읽지 않은 다른 책의 제목","mis":"K6-2-u1-X13"}],"explanation":["소개에는 작품·작가·짐작한 의도·간추린 줄거리·고른 까닭이 들어가요.","책값과 쪽수는 작품이 어떤 작품인지 알려 주지 않아요.","줄거리는 간추려서 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#3','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',1,'ox','auto','「진짜 재미있어요! 안 읽으면 후회함! 별 다섯 개!」만으로도 좋은 작품 소개예요.',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":3,"concept":"K6-2-u1-C8","difficulty":1,"kind":"ox","stem":"「진짜 재미있어요! 안 읽으면 후회함! 별 다섯 개!」만으로도 좋은 작품 소개예요.","answer":"X","reason_options":[{"t":"읽는 사람이 작품이 어떤 작품인지 알 수 없는 광고에 가깝기 때문에","correct":true},{"t":"재미있었다는 마음이 잘 드러나기 때문에","mis":"K6-2-u1-X13"}],"mis":"K6-2-u1-X13","explanation":["소개는 광고가 아니에요.","재미있었다는 말은 한 줄이면 충분해요.","나머지는 작품이 어떤 작품인지로 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#4','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',1,'mc','auto','작가를 알아보고 정리해 학급 게시판에 올릴 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-2-u1-X14','K6-2-u1-X11']::text[],false,'{"seq":4,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"작가를 알아보고 정리해 학급 게시판에 올릴 때 알맞은 방법은 어느 것인가요?","options":[{"t":"찾은 글을 읽고 두세 줄로 간추려 내 말로 쓰고, 어디에서 찾았는지 적는다","correct":true},{"t":"찾은 글을 통째로 복사해 붙인다","mis":"K6-2-u1-X14"},{"t":"찾은 곳은 적지 않아도 된다","mis":"K6-2-u1-X14"},{"t":"작가의 이름만 적는다","mis":"K6-2-u1-X11"}],"explanation":["찾은 글을 그대로 옮기면 남의 글을 내 것처럼 내놓는 일이 돼요.","줄거리를 간추리던 방법을 그대로 써서 내 말로 적어요.","어디에서 찾았는지도 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#5','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',2,'mc','auto','「종을 잃은 마을」을 소개하는 글에 알맞은 문장은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":5,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"「종을 잃은 마을」을 소개하는 글에 알맞은 문장은 어느 것인가요?","options":[{"t":"종이 깨진 마을에서 한 아이가 새벽을 알리는 이야기로, 혼자 시작한 일이 여럿을 움직입니다","correct":true},{"t":"진짜 완전 대박이고 제 인생 책입니다. 무조건 읽으세요","mis":"K6-2-u1-X13"},{"t":"마지막에 새 종이 걸리고 주인공이 첫 소리를 울리며 이야기가 끝납니다","mis":"K6-2-u1-X11"},{"t":"이 이야기는 다섯 쪽이고 그림이 세 장 있습니다","mis":"K6-2-u1-X13"}],"explanation":["읽는 사람이 작품을 고를 수 있게 해 주는 문장이 좋아요.","무엇에 대한 이야기인지, 무엇을 전하는지가 드러나요.","결말을 다 말해 버리면 읽는 즐거움을 빼앗아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#6','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',2,'mc','auto','친구의 작품 소개를 읽고 하기 좋은 물음은 어느 것인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":6,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"친구의 작품 소개를 읽고 하기 좋은 물음은 어느 것인가요?","options":[{"t":"어느 부분을 보고 그렇게 짐작했어?","correct":true},{"t":"이 책 몇 쪽이야?","mis":"K6-2-u1-X13"},{"t":"이거 글씨 큰 책이야?","mis":"K6-2-u1-X13"},{"t":"그 책 얼마야?","mis":"K6-2-u1-X13"}],"explanation":["근거를 묻는 물음이 좋은 물음이에요.","묻는 사람도 답하는 사람도 작품을 한 번 더 읽게 돼요.","쪽수·글씨·값은 작품으로 돌아가게 하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#7','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',2,'sa','auto','작품 소개하는 글의 짜임(처음·가운데·끝)에서 간추린 줄거리와 짐작한 작가의 의도는 어디에 넣나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u1-C8","difficulty":2,"kind":"sa","stem":"작품 소개하는 글의 짜임(처음·가운데·끝)에서 간추린 줄거리와 짐작한 작가의 의도는 어디에 넣나요? 세 글자로 쓰세요.","answer":["가운데"],"explanation":["처음 — 제목·작가·고른 까닭이에요.","가운데 — 간추린 줄거리와 짐작한 의도예요.","끝 — 내 생각과 권할 사람이에요."],"mis":"K6-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#8','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',2,'mc','auto','소개하는 글의 「처음」에 넣을 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X13']::text[],false,'{"seq":8,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"소개하는 글의 「처음」에 넣을 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"작품 제목과 작가, 이 작품을 고른 까닭","correct":true},{"t":"결말까지의 자세한 줄거리","mis":"K6-2-u1-X11"},{"t":"권하고 싶은 사람","mis":"K6-2-u1-X11"},{"t":"책을 산 가게 이름","mis":"K6-2-u1-X13"}],"explanation":["처음에는 무슨 작품인지와 왜 골랐는지를 밝혀요.","「저는 그만둔 일을 아까워한 적이 있어서 이 시를 골랐습니다.」처럼요.","권할 사람은 끝에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#9','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',2,'ox','auto','작품 소개에서 짐작한 작가의 의도를 말할 때는 어디를 보고 그렇게 생각했는지 함께 써요.',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":9,"concept":"K6-2-u1-C8","difficulty":2,"kind":"ox","stem":"작품 소개에서 짐작한 작가의 의도를 말할 때는 어디를 보고 그렇게 생각했는지 함께 써요.","answer":"O","reason_options":[{"t":"근거가 있어야 읽는 사람도 작품을 다시 보며 판단할 수 있기 때문에","correct":true},{"t":"작가의 의도는 하나뿐이라 근거가 없어도 되기 때문에","mis":"K6-2-u1-X06"}],"mis":"K6-2-u1-X06","explanation":["짐작 + 근거를 한 묶음으로 써요.","「‘걷는다’가 되풀이되는 것으로 보아」처럼 근거를 밝혀요.","근거가 있으면 친구와 생각을 나누기도 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_basic#10','kor',6,2,'u1','L12','g6_2_kor_u1_L12_basic','lesson_basic','K6-2-u1-C8',3,'error','auto','작품 소개하는 글을 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X13','K6-2-u1-X14']::text[],false,'{"seq":10,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"작품 소개하는 글을 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「줄거리는 결말까지 한 문장도 빼지 않고 다 적어야 해.」","correct":true,"mis_target":"K6-2-u1-X11"},{"t":"준희 — 「재미있었다는 말은 한 줄이면 충분해.」","mis":"K6-2-u1-X13"},{"t":"이현 — 「찾은 글은 간추려 내 말로 쓰고 출처를 적어.」","mis":"K6-2-u1-X14"}],"explanation":["줄거리는 간추려서 써요.","결말을 다 적으면 통째 옮기기이고 읽는 즐거움도 빼앗아요.","준희와 이현은 이 단원에서 배운 대로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#1','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C9',2,'mc','auto','「약속한 날이 다 찼다.」에서 「찼다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":1,"concept":"K6-2-u1-C9","difficulty":2,"kind":"mc","stem":"「약속한 날이 다 찼다.」에서 「찼다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"정해진 만큼 되었다","correct":true},{"t":"발을 뻗어 세게 내질렀다","mis":"K6-2-u1-X15"},{"t":"몸에 닿는 것이 차가웠다","mis":"K6-2-u1-X15"},{"t":"허리에 매달았다","mis":"K6-2-u1-X15"}],"explanation":["글자가 같아도 뜻이 다른 낱말이 있어요.","「약속한 날이」와 함께 쓰였으니 날짜가 다 되었다는 뜻이에요.","앞뒤 문장을 보아야 어느 뜻인지 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#2','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',2,'mc','auto','소개하는 방법(소개하는 글 · 광고지 · 작가 알아보기 · 말로 소개)이 달라도 같아야 하는 것은 어느 것인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":2,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"소개하는 방법(소개하는 글 · 광고지 · 작가 알아보기 · 말로 소개)이 달라도 같아야 하는 것은 어느 것인가요?","options":[{"t":"담을 내용 — 작품·작가·짐작한 의도·간추린 줄거리·고른 까닭","correct":true},{"t":"글씨 크기와 색깔","mis":"K6-2-u1-X13"},{"t":"작품의 값","mis":"K6-2-u1-X13"},{"t":"그림의 개수","mis":"K6-2-u1-X13"}],"explanation":["방법은 고를 수 있어요.","하지만 담을 내용은 같아요.","작품이 어떤 작품인지 알 수 있게 해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#3','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',3,'mc','auto','「돌아오는 길」을 소개하는 글의 「가운데」로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X14']::text[],false,'{"seq":3,"concept":"K6-2-u1-C8","difficulty":3,"kind":"mc","stem":"「돌아오는 길」을 소개하는 글의 「가운데」로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"가운데 — 잃어버린 것을 세던 사람이 담을 따라 걷다가 뒤에 남은 발자국을 보고 그것이 길이 되었음을 알아차리는 시입니다. 「걷는다」가 되풀이되는 것으로 보아, 잃은 것이 있어도 걸어온 자국은 남는다는 것을 전하려 한 것 같습니다.","correct":true},{"t":"가운데 — 저는 이 시를 별 다섯 개로 추천합니다. 꼭 읽으세요!","mis":"K6-2-u1-X13"},{"t":"가운데 — 누리집에 있던 작가 소개 글을 그대로 붙여 넣었습니다.","mis":"K6-2-u1-X14"},{"t":"가운데 — 이 시는 네 연이고 제목은 다섯 글자입니다.","mis":"K6-2-u1-X13"}],"explanation":["가운데에는 간추린 내용과 짐작한 의도가 들어가요.","「‘걷는다’가 되풀이되는 것으로 보아」처럼 근거도 밝혀요.","광고·통째 옮기기·겉모습 설명은 가운데가 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#4','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',3,'ox','auto','작가를 알아본 글을 학급 게시판에 올릴 때 찾은 글을 그대로 옮기면 남의 글을 내 것처럼 내놓는 일이 돼요.',ARRAY['K6-2-u1-X14']::text[],false,'{"seq":4,"concept":"K6-2-u1-C8","difficulty":3,"kind":"ox","stem":"작가를 알아본 글을 학급 게시판에 올릴 때 찾은 글을 그대로 옮기면 남의 글을 내 것처럼 내놓는 일이 돼요.","answer":"O","reason_options":[{"t":"내가 무엇을 알게 되었는지 드러나지 않고 쓴 사람의 노력을 내 것처럼 쓰는 일이기 때문에","correct":true},{"t":"누리집에 있는 글은 누구나 제 것처럼 써도 되기 때문에","mis":"K6-2-u1-X14"}],"mis":"K6-2-u1-X14","explanation":["찾은 것은 읽고 두세 줄로 간추려 내 말로 적어요.","어디에서 찾았는지 함께 적어요.","간추려 쓰는 방법은 이 단원에서 이미 배웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#5','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C9',3,'match','auto','문장과 밑줄 친 낱말의 뜻을 알맞게 이으세요. (밑줄: 찼다, 찼다, 눈, 눈)','{}'::text[],false,'{"seq":5,"concept":"K6-2-u1-C9","difficulty":3,"kind":"match","stem":"문장과 밑줄 친 낱말의 뜻을 알맞게 이으세요. (밑줄: 찼다, 찼다, 눈, 눈)","pairs":[{"l":"동생이 공을 세게 찼다","r":"발을 뻗어 세게 내질렀다"},{"l":"약속한 날이 다 찼다","r":"정해진 만큼 되었다"},{"l":"밤새 눈이 내렸다","r":"하늘에서 내리는 하얗고 찬 것"},{"l":"할머니는 눈이 밝으시다","r":"사물을 보는 몸의 한 부분"}],"mis":"K6-2-u1-X15","explanation":["같은 글자인데 뜻이 갈려요.","낱말만 보면 알 수 없어요.","그 문장이 무엇에 대한 말인지 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#6','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',3,'error','auto','친구들이 작품 소개를 읽고 물었어요. 작품으로 돌아가게 하지 않는 물음을 한 친구는 누구인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":6,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"친구들이 작품 소개를 읽고 물었어요. 작품으로 돌아가게 하지 않는 물음을 한 친구는 누구인가요?","options":[{"t":"서아 — 「이 책 글씨 커?」","correct":true,"mis_target":"K6-2-u1-X13"},{"t":"준희 — 「어느 부분을 보고 그렇게 짐작했어?」","mis":"K6-2-u1-X13"},{"t":"이현 — 「가장 인상 깊었던 구절은 어디야?」","mis":"K6-2-u1-X13"}],"explanation":["근거나 구절을 묻는 물음은 작품을 다시 보게 해요.","글씨 크기는 작품과 상관없어요.","서로 근거를 물으면 작품이 더 넓어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#7','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C9',3,'mc','auto','「할머니는 눈이 밝으시다.」의 「눈」과 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":7,"concept":"K6-2-u1-C9","difficulty":3,"kind":"mc","stem":"「할머니는 눈이 밝으시다.」의 「눈」과 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"동생은 눈이 좋아 멀리 있는 글씨도 읽는다","correct":true},{"t":"밤새 눈이 내려 길이 하얗다","mis":"K6-2-u1-X15"},{"t":"운동장에서 눈사람을 만들었다","mis":"K6-2-u1-X15"},{"t":"지붕의 눈이 녹아 물이 되었다","mis":"K6-2-u1-X15"}],"explanation":["「눈이 밝으시다」는 잘 본다는 뜻이에요.","사물을 보는 몸의 한 부분인 「눈」이에요.","하늘에서 내리는 눈과 글자는 같지만 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#8','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',4,'mc','auto','「종을 잃은 마을」을 소개하는 글의 「끝」으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":8,"concept":"K6-2-u1-C8","difficulty":4,"kind":"mc","stem":"「종을 잃은 마을」을 소개하는 글의 「끝」으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"혼자 시작한 일이 망설여지는 친구에게 권하고 싶습니다. 늘봄이 나무람을 듣고도 다시 언덕에 오른 장면에서 저도 용기가 났습니다.","correct":true},{"t":"끝으로 이 책은 정말 최고이니 무조건 사세요.","mis":"K6-2-u1-X13"},{"t":"끝에 새 종이 걸리고 늘봄이 첫 소리를 울리며 이야기가 끝납니다.","mis":"K6-2-u1-X11"},{"t":"이 이야기를 쓴 작가의 다른 책 제목은 모릅니다.","mis":"K6-2-u1-X11"}],"explanation":["끝에는 읽고 난 내 생각과 권하고 싶은 사람을 써요.","내 생각에도 작품의 장면을 근거로 들면 좋아요.","결말을 다 말하거나 광고처럼 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#9','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C9',4,'blank','auto','「동생이 공을 세게 (  ).」와 「약속한 날이 다 (  ).」에 똑같이 들어갈 낱말은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":9,"concept":"K6-2-u1-C9","difficulty":4,"kind":"blank","stem":"「동생이 공을 세게 (  ).」와 「약속한 날이 다 (  ).」에 똑같이 들어갈 낱말은 어느 것인가요?","options":[{"t":"찼다","correct":true},{"t":"던졌다","mis":"K6-2-u1-X15"},{"t":"채웠다","mis":"K6-2-u1-X15"},{"t":"넘었다","mis":"K6-2-u1-X15"}],"explanation":["「차다」에는 여러 뜻이 있어요.","발로 내지르다 · 정해진 만큼 되다 — 두 뜻 모두 「찼다」예요.","앞뒤 문장이 어느 뜻인지 정해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_L12_challenge#10','kor',6,2,'u1','L12','g6_2_kor_u1_L12_challenge','lesson_challenge','K6-2-u1-C8',4,'essay','teacher','이 단원에서 읽은 작품(「창문」·「돌아오는 길」·「우산」·「같이 건너세」·「나루를 지켜」·「종을 잃은 마을」·「사흘 걸린 다리」) 가운데 하나를 골라, 처음·가운데·끝의 짜임으로 소개하는 글을 쓰세요. 가운데에는 간추린 줄거리(또는 시의 내용)와 짐작한 작가의 의도를 근거와 함께 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u1-C8","difficulty":4,"kind":"essay","stem":"이 단원에서 읽은 작품(「창문」·「돌아오는 길」·「우산」·「같이 건너세」·「나루를 지켜」·「종을 잃은 마을」·「사흘 걸린 다리」) 가운데 하나를 골라, 처음·가운데·끝의 짜임으로 소개하는 글을 쓰세요. 가운데에는 간추린 줄거리(또는 시의 내용)와 짐작한 작가의 의도를 근거와 함께 넣으세요.","answer_guide":{"answer":"예(「사흘 걸린 다리」): 처음 — 「사흘 걸린 다리」는 떠내려간 징검다리를 다시 놓는 이야기입니다. 저도 혼자 시작했다가 그만둔 일이 있어서 골랐습니다. 가운데 — 큰비에 징검돌이 떠내려가 할머니가 먼 길을 돌아다니자 태건이 혼자 돌을 옮겼고, 쌓은 돌이 무너진 날 아저씨가 거들어 마을 사람들이 함께 다리를 놓았습니다. 돌이 열두 개가 아니라 열네 개가 된 것으로 보아, 한 사람이 시작한 일이 여럿의 힘을 모은다는 것을 전하려 한 것 같습니다. 끝 — 혼자 하는 일이 막막한 친구에게 권하고 싶습니다.","scoring_points":["처음·가운데·끝의 짜임을 갖추었는가","가운데에 간추린 줄거리(내용)와 짐작한 의도·근거를 넣었는가","광고처럼 쓰지 않고 고른 까닭·권할 사람을 밝혔는가"]},"explanation":["처음 — 제목·작가·고른 까닭이에요.","가운데 — 간추린 줄거리 + 의도와 근거예요.","끝 — 내 생각과 권할 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#1','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C1',1,'mc','auto','작가의 의도에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X01','K6-2-u1-X11']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"작가의 의도에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"작가가 작품에 담은 생각과 바람이다","correct":true},{"t":"읽는 사람마다 똑같아야 하는 답이다","mis":"K6-2-u1-X01"},{"t":"작품에 나온 사건을 차례대로 적은 것이다","mis":"K6-2-u1-X11"},{"t":"작가가 쓴 책의 수이다","mis":"K6-2-u1-X01"}],"explanation":["작가의 의도는 쓴 사람 쪽에서 생각해요.","작품에 담은 생각과 바람이에요.","읽는 사람이 근거를 들어 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#2','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C2',1,'mc','auto','「우산」에서 되풀이된 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"「우산」에서 되풀이된 말은 어느 것인가요?","options":[{"t":"덮는다","correct":true},{"t":"어깨는","mis":"K6-2-u1-X03"},{"t":"구석에서","mis":"K6-2-u1-X03"},{"t":"젖는다","mis":"K6-2-u1-X03"}],"explanation":["1연 「남을 덮는다」, 2연 「덮는 동안」, 3연 「덮는 일」, 4연 「또 남을 덮는다」예요.","「덮는다」가 처음과 끝에 되풀이돼요.","되풀이된 말은 눈여겨볼 표시예요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#3','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C5',1,'mc','auto','이야기 구조에서 사건이 본격적으로 생기는 부분은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":3,"concept":"K6-2-u1-C5","difficulty":1,"kind":"mc","stem":"이야기 구조에서 사건이 본격적으로 생기는 부분은 어느 것인가요?","options":[{"t":"전개","correct":true},{"t":"발단","mis":"K6-2-u1-X09"},{"t":"절정","mis":"K6-2-u1-X09"},{"t":"결말","mis":"K6-2-u1-X09"}],"explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#4','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C6',1,'ox','auto','줄거리를 간추릴 때는 덜 중요한 내용을 덜어 내요.',ARRAY['K6-2-u1-X11']::text[],false,'{"seq":4,"concept":"K6-2-u1-C6","difficulty":1,"kind":"ox","stem":"줄거리를 간추릴 때는 덜 중요한 내용을 덜어 내요.","answer":"O","reason_options":[{"t":"중요한 사건만 남겨야 흐름이 잘 보이기 때문에","correct":true},{"t":"글자 수를 줄이는 것만이 목적이기 때문에","mis":"K6-2-u1-X11"}],"mis":"K6-2-u1-X11","explanation":["중요한 사건을 골라요.","덜 중요한 것은 덜어 내요.","고른 사건을 이어지게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#5','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C8',1,'mc','auto','작품 소개하는 글에 넣지 않아도 되는 것은 어느 것인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":5,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"작품 소개하는 글에 넣지 않아도 되는 것은 어느 것인가요?","options":[{"t":"책값과 쪽수","correct":true},{"t":"간추린 줄거리","mis":"K6-2-u1-X13"},{"t":"짐작한 작가의 의도","mis":"K6-2-u1-X13"},{"t":"이 작품을 고른 까닭","mis":"K6-2-u1-X13"}],"explanation":["소개에는 작품이 어떤 작품인지가 들어가요.","줄거리·의도·고른 까닭은 꼭 필요해요.","책값과 쪽수는 작품을 알려 주지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#6','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C9',1,'mc','auto','「모자를 쓰다」의 「쓰다」와 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":6,"concept":"K6-2-u1-C9","difficulty":1,"kind":"mc","stem":"「모자를 쓰다」의 「쓰다」와 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"안경을 쓰고 책을 읽었다","correct":true},{"t":"편지를 쓰다","mis":"K6-2-u1-X15"},{"t":"약이 쓰다","mis":"K6-2-u1-X15"},{"t":"용돈을 쓰다","mis":"K6-2-u1-X15"}],"explanation":["「모자를 쓰다」는 머리나 얼굴에 얹는다는 뜻이에요.","「안경을 쓰다」도 같은 뜻이에요.","앞뒤 말을 보아야 뜻을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#7','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',1,'mc','auto','「거들다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":7,"concept":"K6-2-u1-C7","difficulty":1,"kind":"mc","stem":"「거들다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"남이 하는 일을 옆에서 도와주다","correct":true},{"t":"남의 일을 방해하다","mis":"K6-2-u1-X15"},{"t":"혼자 끝까지 하다","mis":"K6-2-u1-X15"},{"t":"일을 뒤로 미루다","mis":"K6-2-u1-X15"}],"explanation":["「거드는 사람도 말리는 사람도 없었다」에 나와요.","돕는다는 뜻이에요.","앞뒤 문장이 뜻을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#8','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C3',1,'ox','auto','작가의 삶을 알면 작품의 뜻이 하나로 정해져요.',ARRAY['K6-2-u1-X04']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":1,"kind":"ox","stem":"작가의 삶을 알면 작품의 뜻이 하나로 정해져요.","answer":"X","reason_options":[{"t":"작가의 삶은 실마리일 뿐이고 근거는 작품에서 찾아야 하기 때문에","correct":true},{"t":"작가가 쓴 대로만 읽어야 하기 때문에","mis":"K6-2-u1-X04"}],"mis":"K6-2-u1-X04","explanation":["작가의 삶은 읽기를 시작하게 하는 실마리예요.","뜻을 하나로 정해 주지 않아요.","작품으로 돌아와 근거를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#9','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C2',2,'mc','auto','「우산」에서 「덮는다」가 처음과 끝에 되풀이되어 생기는 효과로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X02']::text[],false,'{"seq":9,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「우산」에서 「덮는다」가 처음과 끝에 되풀이되어 생기는 효과로 알맞은 것은 어느 것인가요?","options":[{"t":"한 번이 아니라 되풀이해 온 일임이 드러난다","correct":true},{"t":"시를 읽는 데 걸리는 시간이 길어진다","mis":"K6-2-u1-X03"},{"t":"우산의 색깔을 자세히 알려 준다","mis":"K6-2-u1-X02"},{"t":"비가 그쳤음을 알려 준다","mis":"K6-2-u1-X02"}],"explanation":["1연과 4연에 「남을 덮는다」가 나와요.","4연에는 「또」가 붙어요.","비가 올 때마다 되풀이되는 일임이 드러나요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#10','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C4',2,'mc','auto','「우산」의 「네 어깨는 젖는다」가 나타낸다고 볼 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X08']::text[],false,'{"seq":10,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「우산」의 「네 어깨는 젖는다」가 나타낸다고 볼 수 있는 것은 어느 것인가요?","options":[{"t":"남을 위하느라 자기는 힘들고 손해를 보는 것","correct":true},{"t":"우산이 고장 났다는 것","mis":"K6-2-u1-X08"},{"t":"비가 그쳤다는 것","mis":"K6-2-u1-X08"},{"t":"어깨가 아픈 병이 있다는 것","mis":"K6-2-u1-X08"}],"explanation":["우산은 남을 덮어 주어요.","그동안 자기 어깨는 젖어요.","남을 돕느라 자기는 힘든 모습을 떠올리게 해요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#11','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C1',2,'mc','auto','「우산」을 읽고 예강은 「남을 덮느라 자기는 젖는 부모님 이야기 같아.」, 슬찬은 「끝나면 구석에서 마른다는 게 티 나지 않는 일을 하는 사람 이야기 같아.」라고 했어요. 두 읽기에 대한 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":11,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「우산」을 읽고 예강은 「남을 덮느라 자기는 젖는 부모님 이야기 같아.」, 슬찬은 「끝나면 구석에서 마른다는 게 티 나지 않는 일을 하는 사람 이야기 같아.」라고 했어요. 두 읽기에 대한 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 시에서 근거를 들었으니 둘 다 좋은 읽기다","correct":true},{"t":"작가는 하나만 생각했을 테니 하나는 틀렸다","mis":"K6-2-u1-X06"},{"t":"시에 「부모님」이라는 말이 없으니 예강이 틀렸다","mis":"K6-2-u1-X06"},{"t":"둘 다 느낌일 뿐 근거가 없다","mis":"K6-2-u1-X06"}],"explanation":["예강은 「남을 덮는다」, 「어깨는 젖는다」를 근거로 댔어요.","슬찬은 「구석에서 마른다」를 근거로 댔어요.","근거가 있으면 서로 달라도 좋은 읽기예요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#12','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C5',2,'match','auto','이야기 구조와 「마지막 버스」의 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u1-C5","difficulty":2,"kind":"match","stem":"이야기 구조와 「마지막 버스」의 내용을 알맞게 이으세요.","pairs":[{"l":"발단","r":"하루 세 번 다니는 버스와 경적을 울리던 아저씨"},{"l":"전개","r":"마지막 버스가 없어져 하은이 한 시간을 걸었다"},{"l":"절정","r":"어른들이 고개를 저어도 하은이 한 달 동안 사람 수를 적었다"},{"l":"결말","r":"편지에 이름이 모여 마지막 버스가 다시 다녔다"}],"mis":"K6-2-u1-X09","explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#13','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C6',2,'mc','auto','「마지막 버스」의 줄거리를 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11']::text[],false,'{"seq":13,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「마지막 버스」의 줄거리를 잘 간추린 것은 어느 것인가요?","options":[{"t":"마지막 버스가 없어져 마을 사람들이 불편해지자 하은이 한 달 동안 기다리는 사람 수를 적어 함께 편지를 쓰자고 했고, 어른들이 이름을 적어 버스가 다시 다니게 되었다","correct":true},{"t":"버스가 있었다. 봄이었다. 공책이 있었다. 편지를 썼다.","mis":"K6-2-u1-X10"},{"t":"하은은 정말 착한 아이다.","mis":"K6-2-u1-X11"},{"t":"산골 마을에서 읍내로 가는 버스는 하루 세 번 다녔다. 봉식 아저씨는…(처음부터 그대로)","mis":"K6-2-u1-X11"}],"explanation":["잘 간추린 줄거리는 사건끼리 이어져 있어요.","「~자 ~했고 ~해」처럼 까닭이 보여요.","늘어놓기·느낌·통째 옮기기는 간추린 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#14','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',2,'mc','auto','「마지막 버스」에서 마지막 버스가 없어진 때는 언제인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":14,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「마지막 버스」에서 마지막 버스가 없어진 때는 언제인가요?","options":[{"t":"그해 봄","correct":true},{"t":"이듬달 첫날","mis":"K6-2-u1-X16"},{"t":"한 달 동안","mis":"K6-2-u1-X16"},{"t":"하루 세 번","mis":"K6-2-u1-X16"}],"explanation":["「그해 봄, 버스 회사는 … 마지막 버스를 없앴다.」","「이듬달 첫날」은 다시 다닌 날이에요.","시간을 나타내는 표현으로 일의 차례를 가려요."],"asset":{"type":"passage","lines":["그해 봄, 버스 회사는 손님이 적다며 마지막 버스를 없앴다.","읍내에서 늦게 끝나는 하은은 한 시간을 걸어 돌아왔다.","장 보러 간 어른들도 해 지기 전에 서둘러야 했다."],"title":"「마지막 버스」 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#15','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',2,'mc','auto','「그런다고 회사가 들어주겠니.」라는 말을 듣고도 하은이 계속 적은 데서 알 수 있는 마음은 어느 것인가요?',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":15,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「그런다고 회사가 들어주겠니.」라는 말을 듣고도 하은이 계속 적은 데서 알 수 있는 마음은 어느 것인가요?","options":[{"t":"마을 사람들의 불편을 꼭 바꾸고 싶은 굳은 마음","correct":true},{"t":"어른들을 골탕 먹이려는 마음","mis":"K6-2-u1-X12"},{"t":"공책을 빨리 다 쓰고 싶은 마음","mis":"K6-2-u1-X12"},{"t":"버스 기사가 되고 싶은 마음","mis":"K6-2-u1-X12"}],"explanation":["하은은 자기도, 어른들도 불편해진 것을 겪었어요.","반대하는 말을 듣고도 한 달 동안 적었어요.","앞뒤 사건이 마음을 짐작하는 근거예요."],"asset":{"type":"passage","lines":["하은은 날마다 정류장에서 기다리는 사람 수를 공책에 적었다.","「그런다고 회사가 들어주겠니.」 어른들은 고개를 저었다.","그래도 하은은 한 달 동안 하루도 빼지 않고 적었다.","공책 마지막 장에 「같이 편지를 써 주세요」라고 썼다."],"title":"「마지막 버스」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#16','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C8',2,'mc','auto','「마지막 버스」를 소개하는 글의 「처음」으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":16,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"「마지막 버스」를 소개하는 글의 「처음」으로 알맞은 것은 어느 것인가요?","options":[{"t":"「마지막 버스」는 없어진 버스를 다시 다니게 한 아이의 이야기입니다. 저도 버스로 학원에 다녀서 이 이야기를 골랐습니다.","correct":true},{"t":"완전 강추! 무조건 읽으세요!","mis":"K6-2-u1-X13"},{"t":"이 책은 150쪽이고 값은 8000원입니다.","mis":"K6-2-u1-X13"},{"t":"결국 버스가 다시 다니고 아저씨가 경적을 두 번 울리며 끝납니다.","mis":"K6-2-u1-X11"}],"explanation":["처음에는 무슨 작품인지와 고른 까닭을 써요.","광고나 값은 작품을 알려 주지 않아요.","결말을 다 말하면 읽는 즐거움을 빼앗아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#17','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C3',3,'mc','auto','정다온은 어릴 때 형편이 어려워 연필 한 자루를 오래 아껴 썼습니다. 지금은 아이들에게 글쓰기를 가르치며, 다 쓴 연필을 버리지 않고 모아 둔다고 합니다. 이것을 알고 「다 닳은 연필을 / 버리지 못하고」를 다시 읽을 때 가장 알맞은 짐작은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X04','K6-2-u1-X02']::text[],false,'{"seq":17,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"정다온은 어릴 때 형편이 어려워 연필 한 자루를 오래 아껴 썼습니다. 지금은 아이들에게 글쓰기를 가르치며, 다 쓴 연필을 버리지 않고 모아 둔다고 합니다. 이것을 알고 「다 닳은 연필을 / 버리지 못하고」를 다시 읽을 때 가장 알맞은 짐작은 어느 것인가요?","options":[{"t":"어려운 때를 함께한 작은 것을 소중히 여기는 마음을 전하려 한 것 같다","correct":true},{"t":"연필을 많이 사 두자는 뜻이다","mis":"K6-2-u1-X08"},{"t":"작가가 선생님이니 공부를 열심히 하라는 뜻이다. 끝.","mis":"K6-2-u1-X04"},{"t":"연필은 다 쓰면 바로 버려야 한다는 뜻이다","mis":"K6-2-u1-X02"}],"explanation":["작가는 연필 한 자루를 오래 아껴 썼어요.","그래서 「버리지 못하고」가 그냥 나온 말이 아니겠구나 싶어요.","삶은 실마리, 근거는 「필통 맨 앞에 둔다」 같은 시구예요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#18','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C1',3,'error','auto','「연필」을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X01','K6-2-u1-X06']::text[],false,'{"seq":18,"concept":"K6-2-u1-C1","difficulty":3,"kind":"error","stem":"「연필」을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서아 — 「작가가 생각한 뜻은 하나뿐이니 우리는 그 정답을 맞혀야 해.」","correct":true,"mis_target":"K6-2-u1-X01"},{"t":"준희 — 「‘손안에서 작아진다’를 보면 자기를 내어 주는 이야기 같아.」","mis":"K6-2-u1-X06"},{"t":"이현 — 「‘필통 맨 앞에 둔다’를 보면 고마운 마음이 느껴져.」","mis":"K6-2-u1-X06"}],"explanation":["작가의 의도는 맞혀야 하는 정답이 아니에요.","준희와 이현은 시구를 근거로 댔어요.","근거가 있으면 좋은 읽기예요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#19','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C6',3,'blank','auto','「마지막 버스가 없어져 마을 사람들이 불편해지자 (  ) 어른들이 함께 편지에 이름을 적어 버스가 다시 다니게 되었다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X11','K6-2-u1-X10']::text[],false,'{"seq":19,"concept":"K6-2-u1-C6","difficulty":3,"kind":"blank","stem":"「마지막 버스가 없어져 마을 사람들이 불편해지자 (  ) 어른들이 함께 편지에 이름을 적어 버스가 다시 다니게 되었다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?","options":[{"t":"하은이 한 달 동안 기다리는 사람 수를 적어 함께 편지를 쓰자고 했고,","correct":true},{"t":"봉식 아저씨가 경적을 한 번 더 울렸고,","mis":"K6-2-u1-X09"},{"t":"하은은 한 시간을 걸어 돌아왔고,","mis":"K6-2-u1-X11"},{"t":"그해 봄이 왔고,","mis":"K6-2-u1-X10"}],"explanation":["빈칸에는 절정의 사건이 들어가요.","하은의 공책이 어른들의 이름으로 이어져요.","다른 보기는 흐름을 잇지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#20','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C5',3,'error','auto','「마지막 버스」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X06']::text[],false,'{"seq":20,"concept":"K6-2-u1-C5","difficulty":3,"kind":"error","stem":"「마지막 버스」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「버스가 다시 다니는 곳이 절정이야. 가장 기쁘니까.」","correct":true,"mis_target":"K6-2-u1-X09"},{"t":"준희 — 「어른들이 고개를 저어도 하은이 한 달을 적은 곳이 절정이야.」","mis":"K6-2-u1-X06"},{"t":"이현 — 「마지막 버스가 없어진 곳부터 전개야.」","mis":"K6-2-u1-X06"}],"explanation":["절정은 가장 기쁜 곳이 아니라 갈등이 가장 두드러지는 곳이에요.","버스가 다시 다니는 곳은 결말이에요.","준희와 이현은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#21','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C9',3,'match','auto','「쓰다」가 쓰인 문장과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-2-u1-C9","difficulty":3,"kind":"match","stem":"「쓰다」가 쓰인 문장과 뜻을 알맞게 이으세요.","pairs":[{"l":"편지를 쓰다","r":"글씨로 적다"},{"l":"모자를 쓰다","r":"머리에 얹다"},{"l":"약이 쓰다","r":"맛이 달지 않고 혀가 아리다"},{"l":"용돈을 쓰다","r":"돈을 들이다"}],"mis":"K6-2-u1-X15","explanation":["글자는 같지만 뜻이 네 가지예요.","함께 쓰인 말(편지·모자·약·용돈)이 뜻을 정해요.","앞뒤 말을 보고 가려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#22','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C8',3,'error','auto','작품 소개를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X06','K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":22,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"작품 소개를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「짐작한 의도는 근거 없이 써도 돼.」","correct":true,"mis_target":"K6-2-u1-X06"},{"t":"준희 — 「처음에는 고른 까닭을 써.」","mis":"K6-2-u1-X13"},{"t":"이현 — 「가운데에는 간추린 줄거리를 써.」","mis":"K6-2-u1-X11"}],"explanation":["짐작한 의도에는 근거를 함께 써요.","처음 — 고른 까닭, 가운데 — 줄거리와 의도예요.","준희와 이현은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#23','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C6',4,'mc','auto','「마지막 버스」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":23,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「마지막 버스」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 버스가 없어져 마을 사람들이 불편해지자 하은이 한 달 동안 기다리는 사람 수를 적었다. 그 공책을 본 어른들이 함께 편지에 이름을 적어 이듬달 첫날 버스가 다시 다니게 되었다.","correct":true},{"t":"하은이 있었다. 버스가 있었다. 공책이 있었다. 편지가 있었다.","mis":"K6-2-u1-X10"},{"t":"하은은 착하고, 봉식 아저씨는 친절하다.","mis":"K6-2-u1-X11"},{"t":"버스는 하루 세 번 다녔다. 아저씨는 경적을 울렸다.","mis":"K6-2-u1-X09"}],"explanation":["두 문장 안에 네 부분의 중요한 사건이 다 들어가요.","「~자」, 「그 공책을 본」이 사건을 이어요.","「이듬달 첫날」로 때도 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#24','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C1',4,'essay','teacher','「우산」에서 짐작한 작가의 의도를 한 문장으로 쓰고, 그렇게 짐작한 근거가 되는 시구를 두 가지 드세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u1-C1","difficulty":4,"kind":"essay","stem":"「우산」에서 짐작한 작가의 의도를 한 문장으로 쓰고, 그렇게 짐작한 근거가 되는 시구를 두 가지 드세요.","answer_guide":{"answer":"예: 티 나지 않게 남을 돕는 사람의 마음과 그 고마움을 전하려 한 것 같다. 근거는 「너는 남을 덮는다」·「네 어깨는 젖는다」로 남을 위해 자기가 젖는 모습을 그린 것과, 「접힌 채로 구석에서 마른다」로 일이 끝나면 눈에 띄지 않는 곳에 놓이는 모습을 그린 것이다. 「덮는다」가 처음과 끝에 되풀이되어 이런 일이 계속됨을 드러낸다.","scoring_points":["의도를 한 문장으로 짐작했는가","근거 시구를 두 가지 들었는가","되풀이한 표현의 효과를 근거로 썼는가"]},"explanation":["짐작 + 근거가 한 묶음이에요.","「덮는다」의 되풀이가 좋은 근거예요.","근거가 있으면 다르게 읽어도 좋아요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_a#25','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',4,'essay','teacher','「마지막 버스」에서 시간을 나타내는 표현을 세 가지 찾아 쓰고, 그 표현을 써서 일이 일어난 차례대로 이야기를 세 문장으로 간추리세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u1-C7","difficulty":4,"kind":"essay","stem":"「마지막 버스」에서 시간을 나타내는 표현을 세 가지 찾아 쓰고, 그 표현을 써서 일이 일어난 차례대로 이야기를 세 문장으로 간추리세요.","answer_guide":{"answer":"예: 시간 표현 — 「하루 세 번」, 「그해 봄」, 「한 달 동안」, 「이듬달 첫날」 가운데 세 가지. 간추리기 — 그해 봄 버스 회사가 마지막 버스를 없앴다. 하은은 한 달 동안 정류장에서 기다리는 사람 수를 적어 같이 편지를 쓰자고 했다. 어른들이 편지에 이름을 적었고 이듬달 첫날 마지막 버스가 다시 다니기 시작했다.","scoring_points":["시간을 나타내는 표현을 세 가지 찾았는가","시간 표현을 써서 차례대로 간추렸는가","사건이 이어지게 썼는가"]},"explanation":["시간 표현은 일의 차례를 알려 줘요.","그해 봄 → 한 달 동안 → 이듬달 첫날이에요.","차례를 지키면 흐름이 또렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#1','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C1',1,'mc','auto','같은 작품을 서로 다르게 읽었을 때 좋은 읽기인지 가리는 기준은 어느 것인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"같은 작품을 서로 다르게 읽었을 때 좋은 읽기인지 가리는 기준은 어느 것인가요?","options":[{"t":"작품에서 근거를 들었는가","correct":true},{"t":"작가와 똑같이 읽었는가","mis":"K6-2-u1-X06"},{"t":"더 많은 친구가 그렇게 읽었는가","mis":"K6-2-u1-X06"},{"t":"더 길게 말했는가","mis":"K6-2-u1-X06"}],"explanation":["작품의 주제는 한 사람의 답으로 정해지지 않아요.","맞고 틀림이 아니라 근거가 있고 없음이에요.","근거가 있으면 서로 달라도 좋은 읽기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#2','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C2',1,'mc','auto','「연필」 1연에서 두 번 나온 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"「연필」 1연에서 두 번 나온 말은 어느 것인가요?","options":[{"t":"짧아","correct":true},{"t":"깎을","mis":"K6-2-u1-X03"},{"t":"글씨","mis":"K6-2-u1-X03"},{"t":"길어","mis":"K6-2-u1-X03"}],"explanation":["「짧아진다 / 짧아질수록」에 「짧아」가 두 번 나와요.","「짧아」와 「길어」가 맞서 있어요.","되풀이와 맞섬이 시의 뜻을 가리켜요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#3','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C5',1,'mc','auto','이야기 구조에서 이야기가 마무리되는 부분은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":3,"concept":"K6-2-u1-C5","difficulty":1,"kind":"mc","stem":"이야기 구조에서 이야기가 마무리되는 부분은 어느 것인가요?","options":[{"t":"결말","correct":true},{"t":"발단","mis":"K6-2-u1-X09"},{"t":"전개","mis":"K6-2-u1-X09"},{"t":"절정","mis":"K6-2-u1-X09"}],"explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#4','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C6',1,'ox','auto','사건을 많이 적을수록 잘 간추린 줄거리예요.',ARRAY['K6-2-u1-X10']::text[],false,'{"seq":4,"concept":"K6-2-u1-C6","difficulty":1,"kind":"ox","stem":"사건을 많이 적을수록 잘 간추린 줄거리예요.","answer":"X","reason_options":[{"t":"사건이 이어지게 적는 것이 잘 간추린 것이기 때문에","correct":true},{"t":"빠진 사건이 하나도 없어야 하기 때문에","mis":"K6-2-u1-X10"}],"mis":"K6-2-u1-X10","explanation":["사건을 많이 적는 것이 잘 간추린 것이 아니에요.","사건이 이어지게 적어야 해요.","무슨 일이 왜 일어났는지 드러나야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#5','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C8',1,'mc','auto','작품 소개하는 글의 「끝」에 넣을 내용은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X13']::text[],false,'{"seq":5,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"작품 소개하는 글의 「끝」에 넣을 내용은 어느 것인가요?","options":[{"t":"읽고 난 내 생각과 권하고 싶은 사람","correct":true},{"t":"작품 제목과 작가","mis":"K6-2-u1-X11"},{"t":"간추린 줄거리","mis":"K6-2-u1-X11"},{"t":"책값","mis":"K6-2-u1-X13"}],"explanation":["처음 — 제목·작가·고른 까닭이에요.","가운데 — 줄거리와 의도예요.","끝 — 내 생각과 권할 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#6','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C9',1,'mc','auto','「버스를 타다」의 「타다」와 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":6,"concept":"K6-2-u1-C9","difficulty":1,"kind":"mc","stem":"「버스를 타다」의 「타다」와 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"기차를 타고 할머니 댁에 갔다","correct":true},{"t":"장작이 활활 타다","mis":"K6-2-u1-X15"},{"t":"설탕을 물에 타다","mis":"K6-2-u1-X15"},{"t":"글짓기 대회에서 상을 타다","mis":"K6-2-u1-X15"}],"explanation":["「버스를 타다」는 탈것에 오른다는 뜻이에요.","「기차를 타다」도 같은 뜻이에요.","「타다」는 불이 붙다·섞다·받다라는 뜻도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#7','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C7',1,'mc','auto','「여름내」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":7,"concept":"K6-2-u1-C7","difficulty":1,"kind":"mc","stem":"「여름내」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"여름 한철 동안 내내","correct":true},{"t":"여름이 끝날 때","mis":"K6-2-u1-X15"},{"t":"여름의 첫날","mis":"K6-2-u1-X15"},{"t":"여름에 나는 냄새","mis":"K6-2-u1-X15"}],"explanation":["「여름내 할머니의 걸음은 느려졌다」에 나와요.","「-내」는 「그 동안 내내」라는 뜻을 더해요.","시간을 나타내는 표현이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#8','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C3',1,'ox','auto','작가가 어떤 삶을 살았는지 알면 작품의 말이 다시 보이기도 해요.',ARRAY['K6-2-u1-X04']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":1,"kind":"ox","stem":"작가가 어떤 삶을 살았는지 알면 작품의 말이 다시 보이기도 해요.","answer":"O","reason_options":[{"t":"그냥 지나쳤던 말이 작가의 삶과 이어져 새로 보이기 때문에","correct":true},{"t":"작가의 삶이 곧 작품의 정답이기 때문에","mis":"K6-2-u1-X04"}],"mis":"K6-2-u1-X04","explanation":["「또 한 사람」, 「노 젓던 저 물길」도 그냥 나온 말이 아니었어요.","작가의 삶이 말을 다시 보게 해요.","그래도 근거는 작품 안에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#9','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C2',2,'mc','auto','「연필」 1연에서 「짧아진다」와 「길어진다」를 나란히 놓아 드러내는 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X08']::text[],false,'{"seq":9,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「연필」 1연에서 「짧아진다」와 「길어진다」를 나란히 놓아 드러내는 것은 어느 것인가요?","options":[{"t":"연필이 줄어드는 만큼 글이 늘어난다는 것","correct":true},{"t":"연필과 글씨의 길이는 상관없다는 것","mis":"K6-2-u1-X03"},{"t":"연필을 깎으면 안 된다는 것","mis":"K6-2-u1-X08"},{"t":"글씨를 크게 써야 한다는 것","mis":"K6-2-u1-X08"}],"explanation":["연필은 깎을수록 짧아져요.","그럴수록 글씨는 길어져요.","맞서는 두 말을 나란히 놓아 뜻을 또렷이 해요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#10','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C4',2,'mc','auto','「연필」 3연에서 다 닳은 연필은 무엇을 나타낸다고 볼 수 있나요?',ARRAY['K6-2-u1-X08']::text[],false,'{"seq":10,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「연필」 3연에서 다 닳은 연필은 무엇을 나타낸다고 볼 수 있나요?","options":[{"t":"나와 함께 시간을 보내며 자기를 내어 준 소중한 것","correct":true},{"t":"새로 사야 할 물건","mis":"K6-2-u1-X08"},{"t":"쓸모없어 귀찮은 것","mis":"K6-2-u1-X08"},{"t":"필통을 채우는 장식","mis":"K6-2-u1-X08"}],"explanation":["연필은 손안에서 작아지며 공책을 두껍게 했어요.","다 닳았는데도 버리지 못하고 맨 앞에 둬요.","함께한 시간과 고마움이 담긴 것으로 읽을 수 있어요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#11','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C1',2,'mc','auto','「연필」을 읽고 짐작한 것 가운데 시에서 근거를 들 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X02','K6-2-u1-X06']::text[],false,'{"seq":11,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「연필」을 읽고 짐작한 것 가운데 시에서 근거를 들 수 있는 것은 어느 것인가요?","options":[{"t":"「연필은 손안에서 작아진다」고 했으니 자기를 내어 주는 것에 대한 시 같아","correct":true},{"t":"작가가 선생님이니 공부를 열심히 하라는 시야. 끝.","mis":"K6-2-u1-X04"},{"t":"연필 값이 비싸니 아껴 쓰자는 시야","mis":"K6-2-u1-X02"},{"t":"그냥 슬픈 시야","mis":"K6-2-u1-X06"}],"explanation":["짐작은 시에 적힌 말에서 근거를 찾아요.","「작아진다」와 「두꺼워지고」가 맞서 있어요.","시에 없는 내용이나 근거 없는 느낌은 짐작이 되지 못해요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#12','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C5',2,'match','auto','이야기 구조와 「종을 잃은 마을」의 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u1-C5","difficulty":2,"kind":"match","stem":"이야기 구조와 「종을 잃은 마을」의 내용을 알맞게 이으세요.","pairs":[{"l":"발단","r":"종소리로 하루를 맞추던 마을"},{"l":"전개","r":"금 간 종과 미룬 어른들, 어긋난 마을"},{"l":"절정","r":"나무람 속에서도 열이레 동안 두드린 나무판"},{"l":"결말","r":"다시 모인 사람들과 이듬해 봄의 새 종"}],"mis":"K6-2-u1-X09","explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#13','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C6',2,'mc','auto','「사흘 걸린 다리」의 줄거리를 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":13,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「사흘 걸린 다리」의 줄거리를 잘 간추린 것은 어느 것인가요?","options":[{"t":"징검돌이 떠내려가 할머니가 먼 길을 돌자 태건이 혼자 돌을 옮겼고, 쌓은 돌이 무너진 날 아저씨가 거들러 온 것을 시작으로 어른들이 함께 다리를 다시 놓았다","correct":true},{"t":"돌. 비. 아저씨. 다리.","mis":"K6-2-u1-X10"},{"t":"태건은 할머니를 무척 사랑한다.","mis":"K6-2-u1-X11"},{"t":"할머니는 여덟 번째 돌에서 늘 멈추었다.","mis":"K6-2-u1-X09"}],"explanation":["중요한 사건이 차례대로 이어져요.","까닭(떠내려가 · 무너진 날)이 드러나요.","한 장면만 적거나 느낌만 적으면 줄거리가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#14','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C7',2,'mc','auto','「마지막 버스」에서 마지막 버스가 다시 다니기 시작한 때는 언제인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":14,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「마지막 버스」에서 마지막 버스가 다시 다니기 시작한 때는 언제인가요?","options":[{"t":"이듬달 첫날","correct":true},{"t":"그해 봄","mis":"K6-2-u1-X16"},{"t":"한 달 동안","mis":"K6-2-u1-X16"},{"t":"해 지기 전","mis":"K6-2-u1-X16"}],"explanation":["「이듬달 첫날, 마지막 버스가 다시 다니기 시작했다.」","이듬달은 그다음 달이에요.","시간 표현이 일의 차례를 알려 줘요."],"asset":{"type":"passage","lines":["공책을 본 어른들이 하나둘 편지에 이름을 적었다.","이듬달 첫날, 마지막 버스가 다시 다니기 시작했다.","그날 봉식 아저씨는 정류장마다 경적을 두 번 울렸다."],"title":"「마지막 버스」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#15','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C7',2,'mc','auto','마지막 버스가 다시 다니던 날 봉식 아저씨가 경적을 두 번 울린 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":15,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"마지막 버스가 다시 다니던 날 봉식 아저씨가 경적을 두 번 울린 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 버스를 다시 몰게 되어 기쁘고 고마운 마음","correct":true},{"t":"사람들에게 화가 난 마음","mis":"K6-2-u1-X12"},{"t":"운전이 서툴러 실수한 마음","mis":"K6-2-u1-X12"},{"t":"버스가 고장 나 걱정되는 마음","mis":"K6-2-u1-X12"}],"explanation":["처음에는 경적을 한 번 더 울렸어요.","다시 다니게 된 날에는 두 번 울렸어요.","처음 장면과 견주면 달라진 마음이 보여요."],"asset":{"type":"passage","lines":["공책을 본 어른들이 하나둘 편지에 이름을 적었다.","이듬달 첫날, 마지막 버스가 다시 다니기 시작했다.","그날 봉식 아저씨는 정류장마다 경적을 두 번 울렸다."],"title":"「마지막 버스」 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#16','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C8',2,'mc','auto','「우산」을 소개하는 글의 「가운데」로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X14']::text[],false,'{"seq":16,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"「우산」을 소개하는 글의 「가운데」로 알맞은 것은 어느 것인가요?","options":[{"t":"비가 오면 남을 덮고 그동안 자기 어깨는 젖는 우산을 그린 시입니다. 「덮는다」가 처음과 끝에 되풀이되는 것으로 보아, 티 나지 않게 남을 돕는 마음을 전하려 한 것 같습니다.","correct":true},{"t":"우산은 빨간색이 예쁩니다.","mis":"K6-2-u1-X13"},{"t":"누리집에서 찾은 작가 소개를 그대로 붙였습니다.","mis":"K6-2-u1-X14"},{"t":"최고의 시! 별 다섯!","mis":"K6-2-u1-X13"}],"explanation":["가운데에는 시의 내용과 짐작한 의도가 들어가요.","「되풀이되는 것으로 보아」처럼 근거를 밝혀요.","겉모습·통째 옮기기·광고는 가운데가 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#17','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C3',3,'mc','auto','「우산」은 「돌아오는 길」을 쓴 문해원의 시예요. 문해원은 어릴 때 이사를 자주 다녔고 어른이 되어 같은 골목을 날마다 걸었어요. 이것을 실마리로 「우산」을 읽을 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X05']::text[],false,'{"seq":17,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"「우산」은 「돌아오는 길」을 쓴 문해원의 시예요. 문해원은 어릴 때 이사를 자주 다녔고 어른이 되어 같은 골목을 날마다 걸었어요. 이것을 실마리로 「우산」을 읽을 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"작가의 삶을 실마리로 삼되, 「덮는다」·「젖는다」 같은 시의 말에서 근거를 찾는다","correct":true},{"t":"이사를 다닌 작가이니 이 시도 이사 이야기라고 정한다","mis":"K6-2-u1-X04"},{"t":"「우산」은 작가의 삶과 상관없으니 작가는 생각하지 않는다","mis":"K6-2-u1-X05"},{"t":"「돌아오는 길」과 같은 뜻이라고 그대로 옮겨 쓴다","mis":"K6-2-u1-X04"}],"explanation":["같은 작가라도 작품마다 담은 뜻은 달라요.","작가의 삶은 실마리로 쓰고","근거는 그 작품의 말에서 찾아요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#18','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C1',3,'error','auto','「우산」을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":18,"concept":"K6-2-u1-C1","difficulty":3,"kind":"error","stem":"「우산」을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지호 — 「시에 ‘부모님’이라는 말이 안 나오니 부모님 이야기로 읽으면 틀려.」","correct":true,"mis_target":"K6-2-u1-X06"},{"t":"서호 — 「남을 덮느라 자기는 젖으니 부모님 이야기로도 읽혀.」","mis":"K6-2-u1-X06"},{"t":"수아 — 「구석에서 마른다는 게 티 나지 않게 돕는 사람 같아.」","mis":"K6-2-u1-X06"}],"explanation":["시에 그 낱말이 없어도 근거가 있으면 그렇게 읽을 수 있어요.","서호와 수아는 시구를 근거로 댔어요.","지호는 근거 있는 다른 읽기를 틀렸다고 했어요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#19','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C6',3,'blank','auto','「징검돌이 떠내려가 할머니가 먼 길을 돌아다니자 (  ) 마을 어른들이 함께 다리를 다시 놓았다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X16','K6-2-u1-X11']::text[],false,'{"seq":19,"concept":"K6-2-u1-C6","difficulty":3,"kind":"blank","stem":"「징검돌이 떠내려가 할머니가 먼 길을 돌아다니자 (  ) 마을 어른들이 함께 다리를 다시 놓았다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?","options":[{"t":"태건이 혼자 돌을 옮기기 시작했고, 쌓은 돌이 무너진 날 아저씨가 거들러 오자","correct":true},{"t":"할머니가 여덟 번째 돌에서 멈추었고,","mis":"K6-2-u1-X09"},{"t":"큰비가 사흘 동안 내렸고,","mis":"K6-2-u1-X16"},{"t":"태건이 돌을 하나씩 세었고,","mis":"K6-2-u1-X11"}],"explanation":["빈칸에는 전개 뒤 절정의 사건이 들어가요.","「무너진 날 거들러 오자」가 결말과 이어져요.","앞부분의 일이나 덜 중요한 일은 흐름을 끊어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#20','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C5',3,'error','auto','「사흘 걸린 다리」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X06']::text[],false,'{"seq":20,"concept":"K6-2-u1-C5","difficulty":3,"kind":"error","stem":"「사흘 걸린 다리」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「발단은 할머니가 새 다리를 건너는 곳이야.」","correct":true,"mis_target":"K6-2-u1-X09"},{"t":"서호 — 「쌓은 돌이 무너진 날이 절정이야.」","mis":"K6-2-u1-X06"},{"t":"지호 — 「징검돌이 떠내려간 곳부터 전개야.」","mis":"K6-2-u1-X06"}],"explanation":["할머니가 새 다리를 건너는 곳은 결말이에요.","발단은 징검다리를 건너다니던 처음 모습이에요.","서호와 지호는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#21','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C9',3,'match','auto','「타다」가 쓰인 문장과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-2-u1-C9","difficulty":3,"kind":"match","stem":"「타다」가 쓰인 문장과 뜻을 알맞게 이으세요.","pairs":[{"l":"버스를 타다","r":"탈것에 오르다"},{"l":"장작이 타다","r":"불이 붙어 번지다"},{"l":"설탕을 물에 타다","r":"다른 것에 넣어 섞다"},{"l":"상을 타다","r":"주는 것을 받다"}],"mis":"K6-2-u1-X15","explanation":["「타다」에는 여러 뜻이 있어요.","함께 쓰인 말이 어느 뜻인지 알려 줘요.","낱말만 보면 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#22','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C8',3,'error','auto','작가를 알아보고 소개하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X14','K6-2-u1-X13']::text[],false,'{"seq":22,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"작가를 알아보고 소개하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「작가 소개는 누리집 글을 그대로 붙이면 돼.」","correct":true,"mis_target":"K6-2-u1-X14"},{"t":"서호 — 「작가가 쓴 다른 작품 제목도 찾아 적어.」","mis":"K6-2-u1-X13"},{"t":"지호 — 「알아본 것을 바탕으로 작품을 쓴 의도를 짐작해 적어.」","mis":"K6-2-u1-X13"}],"explanation":["찾은 글은 간추려 내 말로 쓰고 출처를 적어요.","그대로 붙이면 남의 글을 내 것처럼 내놓는 일이 돼요.","서호와 지호는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#23','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C6',4,'mc','auto','「종을 잃은 마을」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":23,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「종을 잃은 마을」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"종에 금이 가고 새 종 만들기를 미루는 사이 마을이 어긋났고, 할아버지마저 앓아눕자 늘봄이 나무판으로 새벽을 알렸다. 나무람을 듣고도 열이레 동안 두드린 소리에 사람들이 다시 모였고, 이듬해 봄 새 종이 걸렸다.","correct":true},{"t":"종이 있었다. 겨울이었다. 나무판이 있었다. 봄이 왔다.","mis":"K6-2-u1-X10"},{"t":"늘봄은 용감하다. 정말 감동적이다.","mis":"K6-2-u1-X11"},{"t":"늘봄은 종소리를 좋아해 하나, 둘, 셋을 세었다. 셋까지 세면 두 번째 소리가 울렸다.","mis":"K6-2-u1-X09"}],"explanation":["네 부분의 중요한 사건이 두 문장에 이어져 있어요.","까닭(미루는 사이 · 앓아눕자 · 그 소리에)이 드러나요.","늘어놓기·느낌·발단만 쓰기는 간추린 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#24','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C3',4,'essay','teacher','정다온은 어릴 때 형편이 어려워 연필 한 자루를 오래 아껴 썼습니다. 지금은 아이들에게 글쓰기를 가르치며, 다 쓴 연필을 버리지 않고 모아 둔다고 합니다. 이것을 실마리로 「연필」에 담긴 작가의 의도를 짐작하고, 시에서 근거가 되는 시구를 두 가지 들어 쓰세요. 작가의 삶만으로 짐작하지 않고 시로 돌아와 확인한 점이 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u1-C3","difficulty":4,"kind":"essay","stem":"정다온은 어릴 때 형편이 어려워 연필 한 자루를 오래 아껴 썼습니다. 지금은 아이들에게 글쓰기를 가르치며, 다 쓴 연필을 버리지 않고 모아 둔다고 합니다. 이것을 실마리로 「연필」에 담긴 작가의 의도를 짐작하고, 시에서 근거가 되는 시구를 두 가지 들어 쓰세요. 작가의 삶만으로 짐작하지 않고 시로 돌아와 확인한 점이 드러나게 쓰세요.","answer_guide":{"answer":"예: 어려운 때를 함께해 준 작은 것을 소중히 여기는 마음을 전하려 한 것 같다. 작가가 연필 한 자루를 오래 아껴 썼다는 것을 알고 나니, 「다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다」가 그냥 나온 말이 아니라고 생각되었다. 시로 돌아와 보면 「연필은 / 손안에서 작아진다」와 「공책은 두꺼워지고」가 맞서 있어, 연필이 자기를 내어 주어 내 글이 자랐다는 고마움이 드러난다.","scoring_points":["의도를 짐작했는가","작가의 삶을 실마리로 썼는가","시구 두 가지로 다시 확인했는가"]},"explanation":["삶은 실마리예요.","근거는 시구에서 찾아요.","두 가지가 같은 쪽을 가리키면 짐작이 단단해요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_b#25','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C1',4,'essay','teacher','「우산」을 읽은 두 친구의 생각이에요. 예강 「남을 덮느라 자기는 젖는 부모님 이야기 같아.」 슬찬 「끝나면 구석에서 마른다는 게 티 나지 않는 일을 하는 사람 이야기 같아.」 두 읽기가 각각 시의 어느 구절을 근거로 했는지 쓰고, 두 읽기를 어떻게 평가하면 좋을지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u1-C1","difficulty":4,"kind":"essay","stem":"「우산」을 읽은 두 친구의 생각이에요. 예강 「남을 덮느라 자기는 젖는 부모님 이야기 같아.」 슬찬 「끝나면 구석에서 마른다는 게 티 나지 않는 일을 하는 사람 이야기 같아.」 두 읽기가 각각 시의 어느 구절을 근거로 했는지 쓰고, 두 읽기를 어떻게 평가하면 좋을지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 예강은 「너는 남을 덮는다」와 「네 어깨는 젖는다」를, 슬찬은 「접힌 채로 구석에서 마른다」를 근거로 했다. 두 사람은 서로 다르게 읽었지만 둘 다 시에서 근거를 들었으므로 둘 다 좋은 읽기이다. 작품의 주제는 한 사람의 답으로 정해지지 않으니, 서로의 근거를 물으며 나누면 시를 더 넓게 읽을 수 있다.","scoring_points":["두 친구의 근거 구절을 바르게 찾았는가","둘 다 근거가 있어 좋은 읽기라고 평가했는가","서로 다른 읽기를 나누는 태도를 썼는가"]},"explanation":["예강 — 덮는다·젖는다, 슬찬 — 구석에서 마른다예요.","근거가 있으면 둘 다 좋은 읽기예요.","서로 근거를 물으면 작품이 넓어져요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#1','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C1',1,'mc','auto','작품을 감상할 때 할 일이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X05','K6-2-u1-X06']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"작품을 감상할 때 할 일이 아닌 것은 어느 것인가요?","options":[{"t":"작품 속 두 생각 가운데 누가 옳은지 가려 내 결론을 말하기","correct":true},{"t":"되풀이한 표현 찾기","mis":"K6-2-u1-X03"},{"t":"작가의 삶 알아보기","mis":"K6-2-u1-X05"},{"t":"근거를 들어 의도 짐작하기","mis":"K6-2-u1-X06"}],"explanation":["감상은 작가가 무엇을 전하려 했는지 짐작하는 일이에요.","누가 옳은지 겨루면 내 결론을 말하게 돼요.","표현·작가의 삶·근거가 감상의 도구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#2','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C2',1,'mc','auto','「돌아오는 길」 3연과 4연에 모두 나온 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"「돌아오는 길」 3연과 4연에 모두 나온 말은 어느 것인가요?","options":[{"t":"길","correct":true},{"t":"발자국","mis":"K6-2-u1-X03"},{"t":"담","mis":"K6-2-u1-X03"},{"t":"주머니","mis":"K6-2-u1-X03"}],"explanation":["3연 「발자국이 길이 된다」, 4연 「길을 내려고 걷는다」예요.","「길」은 제목에도 있어요.","되풀이된 낱말이 시의 뼈대예요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#3','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C5',1,'mc','auto','이야기 구조에서 이야기가 시작되는 부분은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":3,"concept":"K6-2-u1-C5","difficulty":1,"kind":"mc","stem":"이야기 구조에서 이야기가 시작되는 부분은 어느 것인가요?","options":[{"t":"발단","correct":true},{"t":"전개","mis":"K6-2-u1-X09"},{"t":"절정","mis":"K6-2-u1-X09"},{"t":"결말","mis":"K6-2-u1-X09"}],"explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#4','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C6',1,'ox','auto','줄거리를 간추린 뒤에는 이어 읽어 보고 말이 되는지 확인해요.',ARRAY['K6-2-u1-X10']::text[],false,'{"seq":4,"concept":"K6-2-u1-C6","difficulty":1,"kind":"ox","stem":"줄거리를 간추린 뒤에는 이어 읽어 보고 말이 되는지 확인해요.","answer":"O","reason_options":[{"t":"사건이 서로 이어지는지 확인해야 하기 때문에","correct":true},{"t":"맞춤법만 확인하면 되기 때문에","mis":"K6-2-u1-X10"}],"mis":"K6-2-u1-X10","explanation":["간추리기의 마지막 단계예요.","네 문장을 이어 읽어 봐요.","말이 되지 않으면 이음말을 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#5','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C8',1,'mc','auto','「소개는 광고가 아니다」라는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":5,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"「소개는 광고가 아니다」라는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"재미있다는 말보다 작품이 어떤 작품인지 알려 주어야 한다","correct":true},{"t":"작품을 소개하면 안 된다","mis":"K6-2-u1-X13"},{"t":"재미있다는 말을 길게 써야 한다","mis":"K6-2-u1-X13"},{"t":"결말을 꼭 밝혀야 한다","mis":"K6-2-u1-X11"}],"explanation":["광고 같은 말로는 작품을 알 수 없어요.","재미있었다는 말은 한 줄이면 돼요.","나머지는 작품이 어떤 작품인지로 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#6','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C9',1,'mc','auto','「배가 아프다」의 「배」와 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":6,"concept":"K6-2-u1-C9","difficulty":1,"kind":"mc","stem":"「배가 아프다」의 「배」와 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"밥을 많이 먹어 배가 부르다","correct":true},{"t":"배를 타고 섬에 갔다","mis":"K6-2-u1-X15"},{"t":"배가 달고 시원하다","mis":"K6-2-u1-X15"},{"t":"키가 두 배로 자랐다","mis":"K6-2-u1-X15"}],"explanation":["「배가 아프다」의 배는 몸의 한 부분이에요.","「배가 부르다」도 같은 뜻이에요.","탈것·과일·곱절의 「배」와는 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#7','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C7',1,'mc','auto','「나루」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":7,"concept":"K6-2-u1-C7","difficulty":1,"kind":"mc","stem":"「나루」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"강에서 배가 사람을 태우고 건너다니는 곳","correct":true},{"t":"강을 건너는 다리","mis":"K6-2-u1-X15"},{"t":"배를 만드는 곳","mis":"K6-2-u1-X15"},{"t":"강물의 깊이","mis":"K6-2-u1-X15"}],"explanation":["「나루에서 배를 타고 강을 건넜습니다.」","나루는 배가 닿고 떠나는 곳이에요.","다리가 놓이면 나루가 없어질 참이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#8','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C3',1,'ox','auto','작가의 삶은 작품과 상관없으니 알아볼 필요가 없어요.',ARRAY['K6-2-u1-X05']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":1,"kind":"ox","stem":"작가의 삶은 작품과 상관없으니 알아볼 필요가 없어요.","answer":"X","reason_options":[{"t":"작가의 삶은 작품을 다시 보게 하는 실마리이기 때문에","correct":true},{"t":"작품만 읽으면 언제나 다 알 수 있기 때문에","mis":"K6-2-u1-X05"}],"mis":"K6-2-u1-X05","explanation":["작가를 아는 것과 작품을 읽는 것은 둘 다 필요해요.","둘 가운데 하나만 쓰면 감상이 얕아져요.","작가의 삶은 좋은 실마리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#9','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C2',2,'mc','auto','「나루를 지켜」의 「어디로 가겠는가」를 묻는 꼴로 쓴 효과로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X17']::text[],false,'{"seq":9,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「나루를 지켜」의 「어디로 가겠는가」를 묻는 꼴로 쓴 효과로 알맞은 것은 어느 것인가요?","options":[{"t":"「사라지지 않는다」는 뜻을 더 세게 드러낸다","correct":true},{"t":"물길이 어디로 가는지 정말 궁금하다는 뜻이다","mis":"K6-2-u1-X03"},{"t":"답을 몰라 읽는 사람에게 묻는 것이다","mis":"K6-2-u1-X03"},{"t":"시조의 글자 수를 줄이려는 것이다","mis":"K6-2-u1-X17"}],"explanation":["답을 바라는 물음이 아니에요.","「어디로 가겠는가 = 어디로도 가지 않는다」예요.","묻는 꼴로 뜻을 힘주어 말해요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#10','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C4',2,'mc','auto','「창문」의 「같은 유리 / 같은 자리에 서 있는데 / 보이는 것이 바뀐다」가 생각하게 하는 것은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":10,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「창문」의 「같은 유리 / 같은 자리에 서 있는데 / 보이는 것이 바뀐다」가 생각하게 하는 것은 어느 것인가요?","options":[{"t":"같은 것도 때와 마음에 따라 다르게 보인다는 것","correct":true},{"t":"유리를 자주 닦아야 한다는 것","mis":"K6-2-u1-X08"},{"t":"밤에는 창문을 닫아야 한다는 것","mis":"K6-2-u1-X08"},{"t":"창문이 깨졌다는 것","mis":"K6-2-u1-X02"}],"explanation":["창문은 그대로예요.","낮에는 밖이, 밤에는 내가 보여요.","같은 것이 다르게 보이는 데에서 생각이 열려요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#11','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C1',2,'mc','auto','「돌아오는 길」을 읽고 근거를 들어 의도를 짐작한 말은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X06','K6-2-u1-X08']::text[],false,'{"seq":11,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「돌아오는 길」을 읽고 근거를 들어 의도를 짐작한 말은 어느 것인가요?","options":[{"t":"「길을 내려고 걷는다」를 보면 앞으로 나아가려는 다짐을 전하려 한 것 같아","correct":true},{"t":"작가가 이사를 다녔으니 이사에 대한 시야. 끝.","mis":"K6-2-u1-X04"},{"t":"왠지 모르게 쓸쓸해","mis":"K6-2-u1-X06"},{"t":"걷기 운동을 하자는 시야","mis":"K6-2-u1-X08"}],"explanation":["짐작 + 근거가 한 묶음이에요.","마지막 연의 시구가 근거예요.","작가의 삶만이나 느낌만으로는 부족해요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#12','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C5',2,'match','auto','이야기 구조와 「사흘 걸린 다리」의 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u1-C5","difficulty":2,"kind":"match","stem":"이야기 구조와 「사흘 걸린 다리」의 내용을 알맞게 이으세요.","pairs":[{"l":"발단","r":"돌 열두 개를 세며 건너던 징검다리"},{"l":"전개","r":"떠내려간 돌과 한 시간 돌아가는 길"},{"l":"절정","r":"흩어진 돌 앞에 주저앉은 날 찾아온 아저씨"},{"l":"결말","r":"열네 개 돌로 다시 놓인 다리"}],"mis":"K6-2-u1-X09","explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#13','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C6',2,'mc','auto','「종을 잃은 마을」을 한 문장으로 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X02']::text[],false,'{"seq":13,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「종을 잃은 마을」을 한 문장으로 잘 간추린 것은 어느 것인가요?","options":[{"t":"종이 깨져 마을이 어긋나자 늘봄이 나무판으로 새벽을 알렸고, 그 소리에 다시 모인 사람들이 새 종을 걸었다","correct":true},{"t":"종, 겨울, 나무판, 봄.","mis":"K6-2-u1-X10"},{"t":"늘봄은 이불 속에서 하나, 둘, 셋을 세었다.","mis":"K6-2-u1-X11"},{"t":"새 종은 아주 비쌌다.","mis":"K6-2-u1-X02"}],"explanation":["중요한 사건 셋이 이어져요.","「~자 ~했고, 그 소리에」가 흐름을 이어요.","낱말만 늘어놓거나 덜 중요한 장면만 쓰면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#14','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C7',2,'mc','auto','「마지막 버스」에서 하은이 사람 수를 적은 기간은 얼마 동안인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":14,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「마지막 버스」에서 하은이 사람 수를 적은 기간은 얼마 동안인가요?","options":[{"t":"한 달 동안","correct":true},{"t":"하루 세 번","mis":"K6-2-u1-X16"},{"t":"이듬달 첫날","mis":"K6-2-u1-X16"},{"t":"그해 봄 하루","mis":"K6-2-u1-X16"}],"explanation":["「한 달 동안 하루도 빼지 않고 적었다.」","오랫동안 꾸준히 했음을 알려 줘요.","시간 표현은 인물의 끈기도 보여 줘요."],"asset":{"type":"passage","lines":["하은은 날마다 정류장에서 기다리는 사람 수를 공책에 적었다.","「그런다고 회사가 들어주겠니.」 어른들은 고개를 저었다.","그래도 하은은 한 달 동안 하루도 빼지 않고 적었다.","공책 마지막 장에 「같이 편지를 써 주세요」라고 썼다."],"title":"「마지막 버스」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#15','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C7',2,'mc','auto','나무람을 듣고 얼굴이 뜨거워져 내려온 늘봄의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":15,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"나무람을 듣고 얼굴이 뜨거워져 내려온 늘봄의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"부끄럽고 속상한 마음","correct":true},{"t":"자랑스러운 마음","mis":"K6-2-u1-X12"},{"t":"졸린 마음","mis":"K6-2-u1-X12"},{"t":"배고픈 마음","mis":"K6-2-u1-X12"}],"explanation":["「그게 무슨 종소리냐.」 하는 나무람을 들었어요.","잠을 깨운다고 화내는 집도 있었어요.","얼굴이 뜨거워진 것은 부끄럽고 속상해서예요."],"asset":{"type":"passage","lines":["가을 끝 무렵 덕곤 할아버지가 앓아누웠다.","그날 새벽 늘봄은 언덕에 올라 나무판을 두드렸다. 딱, 딱, 딱.","「그게 무슨 종소리냐.」 아랫집 어른이 나와 나무랐다.","늘봄은 얼굴이 뜨거워져 내려왔지만 이튿날 또 올라갔다.","손바닥이 부르터도 열이레 동안 새벽마다 두드렸다."],"title":"「종을 잃은 마을」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#16','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C8',2,'mc','auto','「연필」을 소개하는 글의 「끝」으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X13']::text[],false,'{"seq":16,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"「연필」을 소개하는 글의 「끝」으로 알맞은 것은 어느 것인가요?","options":[{"t":"다 쓴 물건을 쉽게 버리는 친구에게 권하고 싶습니다. 「필통 맨 앞에 둔다」에서 저도 오래 쓴 물건이 떠올랐습니다.","correct":true},{"t":"끝. 다음에는 다른 시를 소개하겠습니다.","mis":"K6-2-u1-X11"},{"t":"연필은 문방구에서 삽니다.","mis":"K6-2-u1-X13"},{"t":"이 시는 세 연이고 제목은 두 글자입니다.","mis":"K6-2-u1-X13"}],"explanation":["끝에는 내 생각과 권할 사람을 써요.","내 생각에도 시구를 근거로 들면 좋아요.","작품과 상관없는 말은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#17','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C3',3,'mc','auto','한도경은 물에 막혀 학교에 가지 못하는 아이들을 보아 왔어요. 이것을 알고 「그 길로 또 한 사람 건너오면 이웃이라」를 다시 읽었을 때 알맞은 짐작은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X08']::text[],false,'{"seq":17,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"한도경은 물에 막혀 학교에 가지 못하는 아이들을 보아 왔어요. 이것을 알고 「그 길로 또 한 사람 건너오면 이웃이라」를 다시 읽었을 때 알맞은 짐작은 어느 것인가요?","options":[{"t":"길이 이어져 사람과 사람이 만나기를 바라는 마음","correct":true},{"t":"다리 공사로 돈을 벌고 싶은 마음","mis":"K6-2-u1-X04"},{"t":"강 건너 사람이 못 오게 막고 싶은 마음","mis":"K6-2-u1-X08"},{"t":"아이들에게 헤엄을 가르치자는 마음","mis":"K6-2-u1-X08"}],"explanation":["작가는 길이 이어지면 사람도 이어진다고 생각했어요.","「건너오면 이웃이라」가 그 생각과 맞닿아요.","삶과 시구가 함께 가리키는 짐작이 단단해요."],"asset":{"type":"passage","lines":["돌 하나 또 한 돌을 놓으면 길이 되고","그 길로 또 한 사람 건너오면 이웃이라","우리도 이같이 놓아 한 마을로 살리라"],"title":"시조 「같이 건너세」 — 한도경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#18','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C7',3,'error','auto','시조 두 편을 읽고 친구들이 말했어요. 감상이 아닌 말을 한 친구는 누구인가요?',ARRAY['K6-2-u1-X07','K6-2-u1-X06']::text[],false,'{"seq":18,"concept":"K6-2-u1-C7","difficulty":3,"kind":"error","stem":"시조 두 편을 읽고 친구들이 말했어요. 감상이 아닌 말을 한 친구는 누구인가요?","options":[{"t":"서아 — 「다리를 놓는 게 당연히 옳으니 ‘같이 건너세’가 더 좋은 시조야.」","correct":true,"mis_target":"K6-2-u1-X07"},{"t":"가온 — 「‘백 번’을 되풀이한 걸 보면 나루를 지키려는 마음이 강해.」","mis":"K6-2-u1-X06"},{"t":"나린 — 「‘한 마을로 살리라’를 보면 두 마을이 이어지길 바랐어.」","mis":"K6-2-u1-X06"}],"explanation":["감상은 각 작가가 무엇을 전하려 했는지 짐작하는 일이에요.","가온과 나린은 표현을 근거로 의도를 짐작했어요.","서아는 작품이 아니라 내 결론을 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#19','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C6',3,'blank','auto','「종이 깨져 (  ) 늘봄이 나무판을 두드려 새벽을 알렸다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?',ARRAY['K6-2-u1-X16','K6-2-u1-X11']::text[],false,'{"seq":19,"concept":"K6-2-u1-C6","difficulty":3,"kind":"blank","stem":"「종이 깨져 (  ) 늘봄이 나무판을 두드려 새벽을 알렸다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?","options":[{"t":"마을이 어긋나고 덕곤 할아버지마저 앓아눕자","correct":true},{"t":"새 종이 걸리자","mis":"K6-2-u1-X16"},{"t":"사람들이 모두 모이자","mis":"K6-2-u1-X16"},{"t":"늘봄이 셋을 세자","mis":"K6-2-u1-X11"}],"explanation":["빈칸은 전개와 절정 사이예요.","할아버지마저 앓아누워 아무도 언덕에 오르지 못하게 되었어요.","새 종·사람들이 모임은 결말의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#20','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C5',3,'error','auto','「종을 잃은 마을」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X06']::text[],false,'{"seq":20,"concept":"K6-2-u1-C5","difficulty":3,"kind":"error","stem":"「종을 잃은 마을」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「결말은 종에 금이 간 곳이야.」","correct":true,"mis_target":"K6-2-u1-X09"},{"t":"가온 — 「늘봄이 나무람을 듣고도 다시 올라간 곳이 절정이야.」","mis":"K6-2-u1-X06"},{"t":"나린 — 「새 종이 걸린 곳이 결말이야.」","mis":"K6-2-u1-X06"}],"explanation":["종에 금이 간 것은 전개의 사건이에요.","결말은 새 종이 걸린 곳이에요.","가온과 나린은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#21','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C9',3,'match','auto','「배」가 쓰인 문장과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-2-u1-C9","difficulty":3,"kind":"match","stem":"「배」가 쓰인 문장과 뜻을 알맞게 이으세요.","pairs":[{"l":"배가 고프다","r":"사람 몸의 한 부분"},{"l":"배를 타고 섬에 가다","r":"물 위로 다니는 탈것"},{"l":"배를 깎아 먹다","r":"물이 많고 단 과일"},{"l":"두 배로 늘다","r":"같은 수를 거듭 더한 만큼"}],"mis":"K6-2-u1-X15","explanation":["「배」는 글자는 같아도 뜻이 갈려요.","고프다·타다·깎다·늘다가 뜻을 정해요.","앞뒤 말을 꼭 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#22','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C8',3,'error','auto','작품 소개에서 줄거리를 다루는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X13']::text[],false,'{"seq":22,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"작품 소개에서 줄거리를 다루는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「결말을 다 말해 줘야 친절한 소개야.」","correct":true,"mis_target":"K6-2-u1-X11"},{"t":"가온 — 「재미있었다는 말은 한 줄이면 충분해.」","mis":"K6-2-u1-X13"},{"t":"나린 — 「권하고 싶은 사람을 끝에 써.」","mis":"K6-2-u1-X11"}],"explanation":["결말까지 다 말하면 읽는 즐거움을 빼앗아요.","줄거리는 간추려 소개해요.","가온과 나린은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#23','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C6',4,'mc','auto','「사흘 걸린 다리」를 한 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X10','K6-2-u1-X09']::text[],false,'{"seq":23,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「사흘 걸린 다리」를 한 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"징검다리가 떠내려가 할머니가 힘들어지자 태건이 혼자 돌을 옮기기 시작했고, 그 모습에 움직인 마을 사람들이 함께 다리를 다시 놓았다","correct":true},{"t":"태건이 다리를 놓았다.","mis":"K6-2-u1-X11"},{"t":"비가 오고, 돌이 떠내려가고, 돌을 옮기고, 비가 오고, 아저씨가 오고, 어른들이 오고, 다리를 놓았다.","mis":"K6-2-u1-X10"},{"t":"할머니는 여덟 번째 돌 앞에서 늘 멈추었다.","mis":"K6-2-u1-X09"}],"explanation":["한 문장이어도 흐름(문제 → 노력 → 함께 해결)이 보여야 해요.","너무 짧으면 뭉뚱그림, 쉼표로 늘어놓으면 나열이에요.","한 장면만 쓰면 줄거리가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#24','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C6',4,'essay','teacher','「마지막 버스」를 발단·전개·절정·결말로 나누어 부분마다 한 문장씩 간추리고, 네 문장이 이어지게 다시 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u1-C6","difficulty":4,"kind":"essay","stem":"「마지막 버스」를 발단·전개·절정·결말로 나누어 부분마다 한 문장씩 간추리고, 네 문장이 이어지게 다시 써 보세요.","answer_guide":{"answer":"예: 발단 — 산골 마을에는 하루 세 번 읍내로 가는 버스가 다녔고, 봉식 아저씨는 마지막 버스 때 경적을 한 번 더 울렸다. 전개 — 그해 봄 회사가 마지막 버스를 없애자 하은과 마을 사람들이 불편해졌다. 절정 — 어른들이 소용없다고 해도 하은은 한 달 동안 기다리는 사람 수를 적고 같이 편지를 쓰자고 했다. 결말 — 공책을 본 어른들이 편지에 이름을 적었고, 이듬달 첫날 버스가 다시 다녀 아저씨는 경적을 두 번 울렸다.","scoring_points":["네 부분으로 나누었는가","부분마다 중요한 사건을 한 문장으로 골랐는가","사건이 까닭으로 이어지게 썼는가"]},"explanation":["부분마다 중요한 사건 하나씩이에요.","「~자」, 「그래도」로 이어요.","시간 표현으로 차례를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_c#25','kor',6,2,'u1','','g6_2_kor_u1_review_c','unit_review','K6-2-u1-C4',4,'essay','teacher','「연필」의 시어 「짧아진다」·「길어진다」·「작아진다」·「두꺼워지고」를 두 묶음으로 나누고, 그렇게 나눈 까닭과 이 시어들이 함께 드러내는 뜻을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u1-C4","difficulty":4,"kind":"essay","stem":"「연필」의 시어 「짧아진다」·「길어진다」·「작아진다」·「두꺼워지고」를 두 묶음으로 나누고, 그렇게 나눈 까닭과 이 시어들이 함께 드러내는 뜻을 쓰세요.","answer_guide":{"answer":"예: 「짧아진다」·「작아진다」는 연필 쪽, 「길어진다」·「두꺼워지고」는 글씨와 공책 쪽이다. 연필은 줄어드는데 내가 쓴 것은 늘어나서 서로 맞서기 때문이다. 이 시어들은 연필이 자기를 내어 주는 만큼 내 글과 공부가 자란다는 뜻을 함께 드러낸다.","scoring_points":["시어를 연필 쪽·글(공책) 쪽으로 나누었는가","줄어듦과 늘어남이 맞선다는 까닭을 썼는가","함께 드러내는 뜻을 짐작해 썼는가"]},"explanation":["줄어드는 말과 늘어나는 말로 나눠요.","두 묶음이 맞서요.","맞섬이 연필이 내어 준 것을 보여 줘요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#1','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C1',1,'mc','auto','「작가의 의도를 짐작한다」는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X01','K6-2-u1-X06','K6-2-u1-X11']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"「작가의 의도를 짐작한다」는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"작품에 담긴 작가의 생각과 바람을 근거를 들어 미루어 생각하는 것","correct":true},{"t":"작가에게 직접 물어 정답을 듣는 것","mis":"K6-2-u1-X01"},{"t":"작가가 생각한 대로만 읽는 것","mis":"K6-2-u1-X06"},{"t":"작품의 줄거리를 외우는 것","mis":"K6-2-u1-X11"}],"explanation":["짐작은 근거를 들어 미루어 생각하는 거예요.","작가가 생각한 대로만 읽으라는 뜻이 아니에요.","내가 읽은 것과 견주며 근거를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#2','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C2',1,'mc','auto','시조 「나루를 지켜」에서 되풀이된 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"시조 「나루를 지켜」에서 되풀이된 말은 어느 것인가요?","options":[{"t":"백 번","correct":true},{"t":"물길","mis":"K6-2-u1-X03"},{"t":"한마음","mis":"K6-2-u1-X03"},{"t":"노 젓던","mis":"K6-2-u1-X03"}],"explanation":["「백 번 고쳐 백 번을 다시 매도」예요.","「백 번」이 두 번 나와요.","몇 번이라도 지키겠다는 뜻을 힘주어 말해요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#3','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C5',1,'mc','auto','이야기 구조의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":3,"concept":"K6-2-u1-C5","difficulty":1,"kind":"mc","stem":"이야기 구조의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"발단 → 전개 → 절정 → 결말","correct":true},{"t":"발단 → 절정 → 전개 → 결말","mis":"K6-2-u1-X09"},{"t":"전개 → 발단 → 결말 → 절정","mis":"K6-2-u1-X09"},{"t":"결말 → 절정 → 전개 → 발단","mis":"K6-2-u1-X09"}],"explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#4','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C6',1,'ox','auto','줄거리를 간추릴 때 「재미있었다」 같은 내 느낌을 꼭 넣어야 해요.',ARRAY['K6-2-u1-X11']::text[],false,'{"seq":4,"concept":"K6-2-u1-C6","difficulty":1,"kind":"ox","stem":"줄거리를 간추릴 때 「재미있었다」 같은 내 느낌을 꼭 넣어야 해요.","answer":"X","reason_options":[{"t":"줄거리는 사건의 흐름을 간추린 것이기 때문에","correct":true},{"t":"느낌이 없으면 줄거리가 아니기 때문에","mis":"K6-2-u1-X11"}],"mis":"K6-2-u1-X11","explanation":["줄거리는 사건의 흐름이에요.","느낌은 소개하는 글의 끝에 써요.","줄거리에는 중요한 사건이 이어지게 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#5','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C8',1,'mc','auto','작가를 알아볼 때 찾은 글을 다루는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X14','K6-2-u1-X11']::text[],false,'{"seq":5,"concept":"K6-2-u1-C8","difficulty":1,"kind":"mc","stem":"작가를 알아볼 때 찾은 글을 다루는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"두세 줄로 간추려 내 말로 쓰고 출처를 적는다","correct":true},{"t":"그대로 복사해 붙인다","mis":"K6-2-u1-X14"},{"t":"찾은 곳을 적지 않는다","mis":"K6-2-u1-X14"},{"t":"작가의 이름만 적는다","mis":"K6-2-u1-X11"}],"explanation":["찾은 글을 그대로 옮기지 않아요.","간추려 내 말로 써요.","어디에서 찾았는지 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#6','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C9',1,'mc','auto','「오래 걸어 다리가 아프다」의 「다리」와 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":6,"concept":"K6-2-u1-C9","difficulty":1,"kind":"mc","stem":"「오래 걸어 다리가 아프다」의 「다리」와 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"달리기를 했더니 다리가 저렸다","correct":true},{"t":"냇물에 다리를 놓았다","mis":"K6-2-u1-X15"},{"t":"다리를 건너 학교에 갔다","mis":"K6-2-u1-X15"},{"t":"다리 밑으로 강물이 흐른다","mis":"K6-2-u1-X15"}],"explanation":["「다리가 아프다」의 다리는 몸을 받치고 걷는 부분이에요.","「다리가 저리다」도 같은 뜻이에요.","건너다니는 「다리」와는 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#7','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C7',1,'mc','auto','「열이레 동안」은 며칠 동안인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":7,"concept":"K6-2-u1-C7","difficulty":1,"kind":"mc","stem":"「열이레 동안」은 며칠 동안인가요?","options":[{"t":"17일 동안","correct":true},{"t":"10일 동안","mis":"K6-2-u1-X15"},{"t":"12일 동안","mis":"K6-2-u1-X15"},{"t":"27일 동안","mis":"K6-2-u1-X15"}],"explanation":["「이레」는 7일이에요.","「열이레」는 10일 + 7일이에요.","늘봄은 17일 동안 새벽마다 나무판을 두드렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#8','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C3',1,'ox','auto','작가의 삶을 알아본 뒤에는 다시 작품으로 돌아와 근거를 찾아요.',ARRAY['K6-2-u1-X04']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":1,"kind":"ox","stem":"작가의 삶을 알아본 뒤에는 다시 작품으로 돌아와 근거를 찾아요.","answer":"O","reason_options":[{"t":"삶은 실마리이고 근거는 작품 안에 있기 때문에","correct":true},{"t":"작가의 삶을 알면 작품을 다시 읽지 않아도 되기 때문에","mis":"K6-2-u1-X04"}],"mis":"K6-2-u1-X04","explanation":["실마리를 얻은 뒤에는 작품으로 돌아와요.","어떤 말이 되풀이되는지, 어떤 장면이 나오는지 확인해요.","그래야 짐작이 단단해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#9','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C2',2,'mc','auto','「창문」의 「밤마다」와 「오래」가 주는 느낌으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":9,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「창문」의 「밤마다」와 「오래」가 주는 느낌으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 번이 아니라 날마다 되풀이되는 느낌","correct":true},{"t":"잠깐 스쳐 지나가는 느낌","mis":"K6-2-u1-X03"},{"t":"밝고 시끄러운 느낌","mis":"K6-2-u1-X08"},{"t":"창문이 새것이라는 느낌","mis":"K6-2-u1-X02"}],"explanation":["「밤마다」는 밤이 올 때마다예요.","「오래」는 짧지 않은 시간이에요.","창문 앞에 서는 일이 되풀이되는 느낌이 들어요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#10','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C4',2,'mc','auto','「돌아오는 길」에서 「길」이 품은 뜻으로 볼 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":10,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「돌아오는 길」에서 「길」이 품은 뜻으로 볼 수 있는 것은 어느 것인가요?","options":[{"t":"걸어가는 길이면서 앞으로 살아갈 날들","correct":true},{"t":"자동차가 다니는 큰길","mis":"K6-2-u1-X08"},{"t":"학교에 가는 지름길","mis":"K6-2-u1-X08"},{"t":"길을 잃은 곳","mis":"K6-2-u1-X02"}],"explanation":["「길을 내려고 걷는다」의 길은 땅 위의 길만이 아니에요.","걸어온 발자국이 길이 된다고 했어요.","시어는 여러 뜻을 품어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#11','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C1',2,'mc','auto','「같이 건너세」를 읽고 근거가 있는 짐작은 어느 것인가요?',ARRAY['K6-2-u1-X02','K6-2-u1-X04','K6-2-u1-X08']::text[],false,'{"seq":11,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「같이 건너세」를 읽고 근거가 있는 짐작은 어느 것인가요?","options":[{"t":"「한 마을로 살리라」로 끝맺은 것을 보면 두 마을이 하나 되기를 바란 것 같아","correct":true},{"t":"다리는 위험하니 놓지 말자는 뜻이야","mis":"K6-2-u1-X02"},{"t":"작가가 다리 놓는 사람이니 자기 일 자랑이야","mis":"K6-2-u1-X04"},{"t":"돌을 많이 모아 두자는 뜻이야","mis":"K6-2-u1-X08"}],"explanation":["힘주어 끝맺은 말은 좋은 근거예요.","「또 한」의 되풀이와 「이웃」도 같은 쪽을 가리켜요.","시조에 없는 내용은 근거가 되지 못해요."],"asset":{"type":"passage","lines":["돌 하나 또 한 돌을 놓으면 길이 되고","그 길로 또 한 사람 건너오면 이웃이라","우리도 이같이 놓아 한 마을로 살리라"],"title":"시조 「같이 건너세」 — 한도경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#12','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C5',2,'match','auto','이야기 구조와 「마지막 버스」의 장면을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u1-C5","difficulty":2,"kind":"match","stem":"이야기 구조와 「마지막 버스」의 장면을 알맞게 이으세요.","pairs":[{"l":"발단","r":"읍내 가는 버스와 마지막 경적"},{"l":"전개","r":"그해 봄 없어진 마지막 버스"},{"l":"절정","r":"한 달 동안 적은 공책과 「같이 편지를 써 주세요」"},{"l":"결말","r":"다시 다니는 버스와 두 번 울린 경적"}],"mis":"K6-2-u1-X09","explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#13','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C6',2,'mc','auto','「마지막 버스」 셋째 부분(절정)을 간추린 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":13,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「마지막 버스」 셋째 부분(절정)을 간추린 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"어른들이 소용없다고 해도 하은은 한 달 동안 기다리는 사람 수를 적고 함께 편지를 쓰자고 했다","correct":true},{"t":"하은은 공책을 한 권 샀다.","mis":"K6-2-u1-X11"},{"t":"봉식 아저씨가 경적을 두 번 울렸다.","mis":"K6-2-u1-X09"},{"t":"버스 회사가 마지막 버스를 없앴다.","mis":"K6-2-u1-X09"}],"explanation":["절정은 갈등이 가장 두드러지는 곳이에요.","어른들의 반대에도 하은이 그만두지 않았어요.","다른 보기는 덜 중요하거나 다른 부분의 일이에요."],"asset":{"type":"passage","lines":["하은은 날마다 정류장에서 기다리는 사람 수를 공책에 적었다.","「그런다고 회사가 들어주겠니.」 어른들은 고개를 저었다.","그래도 하은은 한 달 동안 하루도 빼지 않고 적었다.","공책 마지막 장에 「같이 편지를 써 주세요」라고 썼다."],"title":"「마지막 버스」 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#14','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C7',2,'mc','auto','「마지막 버스」에 나온 말 가운데 시간을 나타내는 표현이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":14,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「마지막 버스」에 나온 말 가운데 시간을 나타내는 표현이 아닌 것은 어느 것인가요?","options":[{"t":"정류장마다","correct":true},{"t":"그해 봄","mis":"K6-2-u1-X16"},{"t":"이듬달 첫날","mis":"K6-2-u1-X16"},{"t":"한 달 동안","mis":"K6-2-u1-X16"}],"explanation":["「정류장마다」는 곳을 나타내요.","「그해 봄·이듬달 첫날·한 달 동안」은 때를 나타내요.","시간 표현에 동그라미하며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#15','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C7',2,'mc','auto','「여름내 할머니의 걸음은 눈에 띄게 느려졌다」에서 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X12','K6-2-u1-X16','K6-2-u1-X02']::text[],false,'{"seq":15,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「여름내 할머니의 걸음은 눈에 띄게 느려졌다」에서 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"먼 길을 돌아다니느라 할머니가 지치고 힘들었다","correct":true},{"t":"할머니가 산책을 즐겼다","mis":"K6-2-u1-X12"},{"t":"징검다리가 다시 놓였다","mis":"K6-2-u1-X16"},{"t":"할머니가 밭일을 그만두었다","mis":"K6-2-u1-X02"}],"explanation":["징검돌이 떠내려가 한 시간을 돌아다녔어요.","그 일이 여름내 이어졌어요.","그래서 걸음이 느려졌다고 짐작할 수 있어요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","어른들은 바쁜 철이니 가을에 놓자고 미루었다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","여름내 할머니의 걸음은 눈에 띄게 느려졌다."],"title":"「사흘 걸린 다리」 둘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#16','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C8',2,'mc','auto','친구의 작품 소개를 읽고 근거를 묻는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":16,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"친구의 작품 소개를 읽고 근거를 묻는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「의도를 그렇게 짐작한 근거가 된 구절은 어디야?」","correct":true},{"t":"「이 책 비싸?」","mis":"K6-2-u1-X13"},{"t":"「그림 많아?」","mis":"K6-2-u1-X13"},{"t":"「몇 쪽짜리야?」","mis":"K6-2-u1-X13"}],"explanation":["근거를 묻는 물음이 좋은 물음이에요.","묻는 사람도 답하는 사람도 작품을 다시 봐요.","값·그림·쪽수는 작품으로 돌아가게 하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#17','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C3',3,'mc','auto','문해원이 어릴 때 낯선 골목을 혼자 걸었다는 것을 알고 「창문」을 다시 읽었어요. 알맞지 않은 읽기는 어느 것인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":17,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"문해원이 어릴 때 낯선 골목을 혼자 걸었다는 것을 알고 「창문」을 다시 읽었어요. 알맞지 않은 읽기는 어느 것인가요?","options":[{"t":"작가가 외로웠으니 이 시는 외로움에 대한 시로 정해져 있다","correct":true},{"t":"「밤마다 … 오래 서 있는다」가 혼자 지낸 시간과 이어져 보인다","mis":"K6-2-u1-X06"},{"t":"「나를 보여 준다」에서 혼자 자신을 들여다보는 모습이 떠오른다","mis":"K6-2-u1-X06"},{"t":"작가의 삶을 알고 나니 같은 시가 조금 다르게 보인다","mis":"K6-2-u1-X06"}],"explanation":["작가의 삶은 시를 다시 보게 해요.","하지만 뜻을 하나로 정해 주지는 않아요.","「정해져 있다」고 하면 다른 근거 있는 읽기를 막아요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#18','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C1',3,'error','auto','「돌아오는 길」을 읽고 친구들이 말했어요. 근거를 들지 않은 친구는 누구인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":18,"concept":"K6-2-u1-C1","difficulty":3,"kind":"error","stem":"「돌아오는 길」을 읽고 친구들이 말했어요. 근거를 들지 않은 친구는 누구인가요?","options":[{"t":"준희 — 「이 시는 그냥 슬퍼. 왜 그런지는 몰라도 돼.」","correct":true,"mis_target":"K6-2-u1-X06"},{"t":"여울 — 「‘만져지는 것이 없다’를 보면 1연은 쓸쓸해.」","mis":"K6-2-u1-X06"},{"t":"라온 — 「‘남은 발자국이 길이 된다’를 보면 3연에서 마음이 놓여.」","mis":"K6-2-u1-X06"}],"explanation":["느낌도 근거가 있어야 나눌 수 있어요.","여울과 라온은 시구를 들었어요.","준희는 까닭을 말하지 않았어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#19','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C6',3,'blank','auto','「하은의 공책을 본 어른들이 편지에 이름을 적자 (  ).」 빈칸에 들어갈 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X16','K6-2-u1-X09']::text[],false,'{"seq":19,"concept":"K6-2-u1-C6","difficulty":3,"kind":"blank","stem":"「하은의 공책을 본 어른들이 편지에 이름을 적자 (  ).」 빈칸에 들어갈 말로 알맞은 것은 어느 것인가요?","options":[{"t":"이듬달 첫날 마지막 버스가 다시 다니기 시작했다","correct":true},{"t":"그해 봄 마지막 버스가 없어졌다","mis":"K6-2-u1-X16"},{"t":"하은은 한 시간을 걸어 돌아왔다","mis":"K6-2-u1-X16"},{"t":"봉식 아저씨가 경적을 한 번 더 울렸다","mis":"K6-2-u1-X09"}],"explanation":["결말의 사건이 들어가요.","「이듬달 첫날」이 차례를 알려 줘요.","앞부분의 일을 넣으면 차례가 뒤엉켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#20','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C5',3,'error','auto','이야기 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X06']::text[],false,'{"seq":20,"concept":"K6-2-u1-C5","difficulty":3,"kind":"error","stem":"이야기 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「절정은 언제나 이야기의 맨 마지막 문장이야.」","correct":true,"mis_target":"K6-2-u1-X09"},{"t":"여울 — 「절정은 갈등이 가장 두드러지는 곳이야.」","mis":"K6-2-u1-X06"},{"t":"라온 — 「경계는 까닭을 말할 수 있으면 사람마다 조금 달라도 돼.」","mis":"K6-2-u1-X06"}],"explanation":["절정은 맨 끝이 아니라 결말 바로 앞에 오는 일이 많아요.","갈등이 가장 두드러지는 곳을 찾아요.","여울과 라온은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#21','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C9',3,'match','auto','「손」이 쓰인 문장과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-2-u1-C9","difficulty":3,"kind":"match","stem":"「손」이 쓰인 문장과 뜻을 알맞게 이으세요.","pairs":[{"l":"손을 깨끗이 씻다","r":"팔목 끝에 달린 몸의 부분"},{"l":"일손이 모자라 손이 부족하다","r":"일을 할 사람"},{"l":"손이 많이 가는 음식","r":"일에 드는 수고"}],"mis":"K6-2-u1-X15","explanation":["「손」은 몸의 부분만 뜻하지 않아요.","「손이 부족하다」는 사람이 모자라다는 뜻이에요.","「손이 많이 가다」는 수고가 든다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#22','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C8',3,'error','auto','작품 소개 광고지를 만드는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X13']::text[],false,'{"seq":22,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"작품 소개 광고지를 만드는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「‘대박·별 다섯’만 크게 쓰면 돼.」","correct":true,"mis_target":"K6-2-u1-X13"},{"t":"여울 — 「광고지에도 짐작한 의도를 한 줄 넣어.」","mis":"K6-2-u1-X13"},{"t":"라온 — 「인상 깊은 구절을 하나 골라 넣어.」","mis":"K6-2-u1-X13"}],"explanation":["광고지도 소개예요 — 담을 내용은 같아요.","작품이 어떤 작품인지 알 수 있어야 해요.","여울과 라온은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#23','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C6',4,'mc','auto','「마지막 버스」를 간추린 글 가운데 「뭉뚱그림」에 해당하는 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11']::text[],false,'{"seq":23,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「마지막 버스」를 간추린 글 가운데 「뭉뚱그림」에 해당하는 것은 어느 것인가요?","options":[{"t":"어떤 아이 덕분에 일이 잘 풀렸다.","correct":true},{"t":"버스가 있었다. 봄이 왔다. 공책을 썼다. 버스가 왔다.","mis":"K6-2-u1-X10"},{"t":"마지막 버스가 없어지자 하은이 사람 수를 적어 편지를 쓰자고 했고, 어른들이 함께해 버스가 다시 다녔다.","mis":"K6-2-u1-X11"},{"t":"산골 마을에서 읍내로 가는 버스는 하루 세 번 다녔다. 봉식 아저씨는…(처음부터 그대로)","mis":"K6-2-u1-X11"}],"explanation":["뭉뚱그림은 흐름만 말하고 사건을 고르지 않은 것이에요.","무엇이, 어떻게 풀렸는지 사건이 하나도 없어요.","늘어놓기는 나열, 처음부터 그대로는 통째 옮기기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#24','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C8',4,'essay','teacher','「마지막 버스」를 친구에게 소개하는 글을 처음·가운데·끝의 짜임으로 쓰세요. 가운데에는 간추린 줄거리와 짐작한 작가의 의도를 근거와 함께 넣으세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u1-C8","difficulty":4,"kind":"essay","stem":"「마지막 버스」를 친구에게 소개하는 글을 처음·가운데·끝의 짜임으로 쓰세요. 가운데에는 간추린 줄거리와 짐작한 작가의 의도를 근거와 함께 넣으세요.","answer_guide":{"answer":"예: 처음 — 「마지막 버스」는 없어진 버스를 다시 다니게 한 아이의 이야기입니다. 저도 버스를 타고 다녀서 골랐습니다. 가운데 — 마지막 버스가 없어져 마을이 불편해지자 하은이 한 달 동안 기다리는 사람 수를 적었고, 그 공책을 본 어른들이 함께 편지를 써 버스가 다시 다니게 됩니다. 어른들이 고개를 저어도 하은이 그만두지 않은 장면으로 보아, 작은 기록과 끈기가 여럿의 마음을 움직인다는 것을 전하려 한 것 같습니다. 끝 — 무언가를 바꾸고 싶지만 혼자라 망설이는 친구에게 권하고 싶습니다.","scoring_points":["처음·가운데·끝의 짜임을 갖추었는가","가운데에 간추린 줄거리와 의도·근거를 넣었는가","고른 까닭과 권할 사람을 밝히고 광고처럼 쓰지 않았는가"]},"explanation":["처음 — 제목·고른 까닭이에요.","가운데 — 줄거리 + 의도와 근거예요.","끝 — 내 생각과 권할 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u1_review_d#25','kor',6,2,'u1','','g6_2_kor_u1_review_d','unit_review','K6-2-u1-C9',4,'essay','teacher','「쓰다」의 서로 다른 뜻 두 가지가 드러나게 짧은 문장을 하나씩 만들고, 글을 읽다가 여러 뜻을 지닌 낱말을 만났을 때 뜻을 가려 읽는 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u1-C9","difficulty":4,"kind":"essay","stem":"「쓰다」의 서로 다른 뜻 두 가지가 드러나게 짧은 문장을 하나씩 만들고, 글을 읽다가 여러 뜻을 지닌 낱말을 만났을 때 뜻을 가려 읽는 방법을 쓰세요.","answer_guide":{"answer":"예: 「동생에게 편지를 썼다.」(글씨로 적다) 「햇볕이 뜨거워 모자를 썼다.」(머리에 얹다) 여러 뜻을 지닌 낱말을 만나면 낱말만 보지 않고 함께 쓰인 말과 앞뒤 문장을 보아 그 문장이 무엇에 대한 말인지 따져 알맞은 뜻을 고른다.","scoring_points":["「쓰다」의 서로 다른 뜻 두 가지로 문장을 만들었는가","각 문장의 뜻을 바르게 밝혔는가","앞뒤 문장(함께 쓰인 말)으로 뜻을 가린다는 방법을 썼는가"]},"explanation":["함께 쓰인 말이 뜻을 정해요.","편지를 쓰다 · 모자를 쓰다 · 약이 쓰다 · 돈을 쓰다예요.","낱말만 보면 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
